const reqState = {};
function alfBlock(){
  return `<div class="card alf" id="alfandega">
    <div class="alf-top"><div><div class="k">A alfândega processual</div><h4>Checklist de admissibilidade</h4></div>
      <div class="verdict" id="verdict"><span class="bar"><i></i></span><span id="vtxt"></span><b id="vres"></b><button id="vclr">Limpar</button></div></div>
    <div class="alf-cols">${['intr','extr'].map(k => { const g = REQ[k]; return `<div class="alf-col" style="--ac:var(${g.c})"><h5>${g.t}</h5><p>${g.p}</p>
      ${g.i.map((r, i) => `<label class="req" data-k="${k}${i}"><input type="checkbox" data-k="${k}${i}"><div><b>${r.t}</b> <span class="pl">— ${r.pl}</span></div><div class="tc">${r.tc}${r.lex ? ` <a href="#" data-lex="${r.lex}" style="color:var(--ac)">verbete ›</a>` : ''}</div></label>`).join('')}</div>`; }).join('')}</div>
  </div>`;
}
function updVerdict(){
  const tot = REQ.intr.i.length + REQ.extr.i.length;
  const n = Object.values(reqState).filter(Boolean).length;
  const v = $('#verdict'); if (!v) return;
  v.querySelector('.bar i').style.width = (n / tot * 100) + '%';
  $('#vtxt').textContent = `${n}/${tot} conferidos`;
  $('#vres').textContent = n === tot ? '→ requisitos conferidos' : '→ conferência em andamento';
  v.classList.toggle('ok', n === tot);
  document.querySelectorAll('.req').forEach(l => l.classList.toggle('on', !!reqState[l.dataset.k]));
}
function bindAlf(){
  document.querySelectorAll('.req input').forEach(c => c.onchange = () => { reqState[c.dataset.k] = c.checked; updVerdict(); });
  $('#vclr').onclick = () => { for (const k in reqState) reqState[k] = false; document.querySelectorAll('.req input').forEach(c => c.checked = false); updVerdict(); };
  document.querySelectorAll('[data-lex]').forEach(a => a.onclick = e => { e.preventDefault(); e.stopPropagation(); gotoTerm(a.dataset.lex); });
  updVerdict();
}
function matrixBlock(){
  return `<div class="phases">
      <div class="phase"><span class="n">1ª fase · admissibilidade</span><b>Conhecimento</b><i>“Este recurso cumpre as regras do jogo para entrar?”</i></div>
      <div class="arr">→</div>
      <div class="phase"><span class="n">2ª fase · mérito</span><b>Provimento</b><i>“Quem recorreu tem razão no que reclama?” — só se conhecido.</i></div>
    </div>
    <div class="matrix">
      <div class="h"></div><div class="h">Dá provimento</div><div class="h">Nega provimento</div>
      <div class="r">Conhecido</div>
      <div class="c y"><b>Conhecido e provido</b>Passou pela porta e o recorrente tinha razão: a decisão é reformada ou anulada.</div>
      <div class="c n"><b>Conhecido e improvido</b>Estava no prazo e com custas pagas, mas não tinha razão no direito: decisão mantida.</div>
      <div class="r">Não conhecido</div>
      <div class="c x" style="grid-column:span 2"><b>Não conhecido — e jamais provido</b>Barrado na entrada, o recurso não chega ao mérito: não há “não conhecido e provido”. O dispositivo para em “não conheço do recurso”.</div>
    </div>`;
}


