function buildLex(){
  const L = $('#lex');
  L.innerHTML = LEXG.map(g => {
    const items = LEX.filter(x => x.g === g.id);
    let extra = '';
    if (g.id === 'entrada') extra = `<button class="card jumpcard" onclick="goRot('chegada')"><b>✦ Checklist de admissibilidade</b><span>A alfândega processual — requisitos intrínsecos e extrínsecos — está na aba Fluxos e Rotina, etapa 1.</span></button>`;
    if (g.id === 'resultado') extra = matrixBlock() + `
      <div class="card porta"><div class="mini" id="porta"></div>
      <div class="verbs">
        <div class="verb" style="--vc:var(--muted)"><b>Não conheço</b><code>barrado na admissibilidade</code></div>
        <div class="verb" style="--vc:var(--navy)"><b>Conheço</b><code>passa ao mérito</code></div>
        <div class="verb" style="--vc:var(--green)"><b>Dou provimento</b><code>reforma ou anula</code></div>
        <div class="verb" style="--vc:var(--wine)"><b>Nego provimento</b><code>mantém a decisão</code></div>
      </div></div>`;
    return `<div class="lexgrp" style="--lc:var(${g.c})">
      <h3>${g.t}<small>${g.s} · ${items.length} verbetes</small></h3><p>${g.p}</p>${extra}
      <div class="lexgrid">${items.map(x => `
        <details class="term" data-t="${x.t}">
          <summary><b>${x.t}</b><span class="lat">${x.lat}</span><span class="def">${x.d}</span></summary>
          <div class="tb">
            <h5>Em detalhe</h5><ul>${x.det.map(d => `<li>${d}</li>`).join('')}</ul>
            <div class="gab"><b>No gabinete ·</b> ${x.gab}</div>
            <div class="chips">${x.base.map(b => `<span>${b}</span>`).join('')}${x.rel.map(r => `<button data-rel="${r}">✦ ${scById[r].t}</button>`).join('')}</div>
          </div>
        </details>`).join('')}</div></div>`;
  }).join('');
  L.querySelectorAll('[data-rel]').forEach(b => b.onclick = e => { e.preventDefault(); openSC(b.dataset.rel); });
  draw($('#porta'), PORTA);
}
function filterLex(){
  const v = $('#lq').value.trim().toLowerCase();
  document.querySelectorAll('#lex details.term').forEach(d => {
    const hit = !v || d.textContent.toLowerCase().includes(v);
    d.classList.toggle('hide', !hit);
    if (v && hit) d.open = true;
  });
  document.querySelectorAll('#lex .lexgrp').forEach(g => {
    g.style.display = [...g.querySelectorAll('details.term')].some(d => !d.classList.contains('hide')) ? '' : 'none';
  });
}
function gotoTerm(t){
  if ($('#dlg').open) $('#dlg').close();
  if ($('#pal').open) $('#pal').close();
  showTab('lexico');
  $('#lq').value = ''; filterLex();
  const d = document.querySelector(`#lex details.term[data-t="${t}"]`);
  if (d){ d.open = true; d.scrollIntoView({behavior:'smooth', block:'center'}); }
}


/* =================== UTILITÁRIOS =================== */
const $ = s => document.querySelector(s);
const root = document.documentElement;
const cssv = n => getComputedStyle(root).getPropertyValue(n).trim();
const isDark = () => root.dataset.theme === 'dark';
const byId = Object.fromEntries(R.map(r => [r.id, r]));
const scById = Object.fromEntries(SC.map(s => [s.id, s]));

function palette(){
  return isDark() ? {
    org:['#132f40','#77bae6','#e4e8eb'], rec:['#0e364d','#70c3f9','#f3e7c6'],
    step:['#24282c','#4a5162','#e4e8eb'], dec:['#3a222a','#e68e9b','#f6dfe3'],
    fim:['#1e3325','#86c99d','#dff3e8'], line:'#80858a', bg:'#1b1f23', text:'#e4e8eb'
  } : {
    org:['#e9eef4','#003f5d','#003f5d'], rec:['#ecf0f3','#3e87b4','#0d354c'],
    step:['#f8fcff','#bdb39c','#212529'], dec:['#fbecee','#7a2e3a','#5a1f29'],
    fim:['#e5f2ea','#366a4a','#21452f'], line:'#8b8574', bg:'#fcfdff', text:'#212529'
  };
}
function initMermaid(){
  if (!window.mermaid) return;
  const p = palette();
  mermaid.initialize({
    startOnLoad:false, theme:'base', securityLevel:'loose',
    themeVariables:{ fontFamily:'Figtree, system-ui, sans-serif', fontSize:'13.5px',
      lineColor:p.line, primaryTextColor:p.text, edgeLabelBackground:p.bg, background:p.bg },
    flowchart:{ curve:'basis', htmlLabels:true, nodeSpacing:30, rankSpacing:42, padding:12, useMaxWidth:true }
  });
}
let mc = 0;
async function draw(el, src){
  if (!window.mermaid){ el.innerHTML = '<p class="err">Os fluxogramas dependem de conexão com a internet. Verifique-a e recarregue a página.</p>'; return; }
  const p = palette();
  const defs = ['org','rec','step','dec','fim'].map(k =>
    `classDef ${k} fill:${p[k][0]},stroke:${p[k][1]},color:${p[k][2]},stroke-width:1.6px`).join('\n');
  try { const { svg } = await mermaid.render('mm' + (++mc), src + '\n' + defs); el.innerHTML = svg; }
  catch(e){ el.innerHTML = '<p class="err">Não foi possível desenhar este fluxo.</p>'; }
}


/* =================== MAPA MENTAL =================== */
const state = { sel:null, tab:'ess', q:'', checks:{} };

function buildMap(){
  $('#branches').innerHTML = Object.entries(FAM).map(([k,f]) => {
    const items = R.filter(r => r.fam === k);
    return `<div class="branch" data-fam="${k}" style="--fc:var(${f.c})">
      <button class="fam" data-fam="${k}" aria-expanded="true"><span class="count">${items.length}</span><b>${f.n}</b><small>${f.s}</small></button>
      <div class="leaves">${items.map(r => `<button class="leaf" data-id="${r.id}"><span>${r.nome}</span><span class="bdg">${r.badge}</span></button>`).join('')}</div>
    </div>`;
  }).join('');
  document.querySelectorAll('.leaf').forEach(b => b.onclick = () => select(b.dataset.id, true));
  document.querySelectorAll('.fam').forEach(b => b.onclick = () => {
    const br = b.closest('.branch'); br.classList.toggle('collapsed');
    b.setAttribute('aria-expanded', !br.classList.contains('collapsed')); drawLinks();
  });
  $('#rootNode').onclick = () => { document.querySelectorAll('.branch').forEach(b => b.classList.remove('collapsed')); drawLinks(); };
}

function drawLinks(){
  const map = $('#map'), svg = $('#links');
  if (getComputedStyle(svg).display === 'none') return;
  const M = map.getBoundingClientRect();
  svg.setAttribute('viewBox', `0 0 ${M.width} ${M.height}`);
  const pt = (el, side) => { const r = el.getBoundingClientRect();
    return [ (side === 'r' ? r.right : r.left) - M.left, r.top + r.height/2 - M.top ]; };
  const curve = (a, b) => { const dx = (b[0]-a[0]) * .5;
    return `M${a[0]},${a[1]} C${a[0]+dx},${a[1]} ${b[0]-dx},${b[1]} ${b[0]},${b[1]}`; };
  const rootEl = $('#rootNode'); let html = '';
  const selFam = state.sel ? byId[state.sel].fam : null;
  document.querySelectorAll('.branch').forEach(br => {
    const fam = br.dataset.fam, color = cssv(FAM[fam].c), famBtn = br.querySelector('.fam');
    html += `<path d="${curve(pt(rootEl,'r'), pt(famBtn,'l'))}" stroke="${color}" class="${br.classList.contains('dimmed')?'dim':''} ${selFam===fam?'hot':''}"/>`;
    if (!br.classList.contains('collapsed')) br.querySelectorAll('.leaf').forEach(lf => {
      const cls = (lf.classList.contains('dimmed') ? 'dim ' : '') + (lf.dataset.id === state.sel ? 'hot' : '');
      html += `<path d="${curve(pt(famBtn,'r'), pt(lf,'l'))}" stroke="${color}" class="${cls}"/>`;
    });
  });
  svg.innerHTML = html;
}

function filter(){
  const q = state.q.trim().toLowerCase();
  document.querySelectorAll('.leaf').forEach(lf => {
    const r = byId[lf.dataset.id];
    const hay = (r.nome+' '+r.kw+' '+r.base+' '+r.prazo+' '+r.contra+' '+r.orgao+' '+r.ess.join(' ')).toLowerCase();
    lf.classList.toggle('dimmed', !!q && !hay.includes(q));
  });
  document.querySelectorAll('.branch').forEach(br => {
    const any = [...br.querySelectorAll('.leaf')].some(l => !l.classList.contains('dimmed'));
    br.classList.toggle('dimmed', !!q && !any);
    if (q && any) br.classList.remove('collapsed');
  });
  drawLinks();
}

/* =================== PAINEL =================== */
function select(id, scroll){
  state.sel = id;
  document.querySelectorAll('.leaf').forEach(l => l.classList.toggle('active', l.dataset.id === id));
  document.querySelector(`.branch[data-fam="${byId[id].fam}"]`).classList.remove('collapsed');
  renderPanel(); drawLinks();
  if (scroll && innerWidth <= 900 && $('#panel').offsetParent) $('#panel').scrollIntoView({behavior:'smooth', block:'start'});
}

function renderPanel(){
  const r = byId[state.sel], f = FAM[r.fam], idx = R.indexOf(r);
  const P = $('#panel'); P.style.setProperty('--fc', `var(${f.c})`);
  const tabs = [['ess','Essencial'],['rot','Gabinete & rotina'],['flx','Fluxo']];
  let body = '';
  if (state.tab === 'ess'){
    body = `<ul class="bul">${r.ess.map(x => `<li>${x}</li>`).join('')}</ul><div class="atn">${r.atn}</div>`;
  } else if (state.tab === 'rot'){
    body = r.rot.map((g, gi) => {
      const done = g.i.filter((_, ii) => state.checks[`${r.id}-${gi}-${ii}`]).length;
      return `<div class="grp"><h4>${g.t}<small>${done}/${g.i.length}</small></h4>${g.i.map((it, ii) => {
        const k = `${r.id}-${gi}-${ii}`, on = !!state.checks[k];
        return `<label class="chk ${on?'done':''}"><input type="checkbox" data-k="${k}" ${on?'checked':''}><span>${it}</span></label>`;
      }).join('')}</div>`;
    }).join('');
  } else {
    body = `<div class="mini" id="mini"><p style="color:var(--muted);font-size:13px">Desenhando o fluxo…</p></div>`;
  }
  const prev = R[(idx - 1 + R.length) % R.length], next = R[(idx + 1) % R.length];
  P.innerHTML = `
    <div class="ph-fam">${f.n} · ${f.s}</div>
    <div class="ph-title">${r.nome}</div>
    <div class="ph-base">${r.base}</div>
    <div class="stats">
      <div class="stat"><span>Prazo</span><b>${r.prazo}</b></div>
      <div class="stat"><span>Cabe contra</span><b>${r.contra}</b></div>
      <div class="stat"><span>Órgão julgador</span><b>${r.orgao}</b></div>
      <div class="stat"><span>Sustentação oral</span><b>${r.sust}</b></div>
    </div>
    <div class="tabs" role="tablist">${tabs.map(([k,l]) => `<button class="tab ${state.tab===k?'on':''}" data-t="${k}" role="tab">${l}</button>`).join('')}</div>
    <div>${body}</div>
    <div class="relsc">${r.sc.map(s => `<button data-rel="${s}">✦ ${scById[s].t}</button>`).join('')}</div>
    <div class="pnav"><button data-go="${prev.id}">‹ ${prev.nome}</button><button data-go="${next.id}">${next.nome} ›</button></div>`;
  P.querySelectorAll('.tab').forEach(b => b.onclick = () => { state.tab = b.dataset.t; renderPanel(); });
  P.querySelectorAll('[data-go]').forEach(b => b.onclick = () => select(b.dataset.go));
  P.querySelectorAll('[data-rel]').forEach(b => b.onclick = () => openSC(b.dataset.rel));
  P.querySelectorAll('input[data-k]').forEach(c => c.onchange = () => { state.checks[c.dataset.k] = c.checked; renderPanel(); });
  if (state.tab === 'flx') draw($('#mini'), r.flow);
}

/* =================== GRANDES FLUXOS =================== */
let bigIdx = 0;
function buildBig(){
  if (!$('#ftabs') || !$('#bigflow')) return;
  $('#ftabs').innerHTML = BIG.map((b, i) => `<button class="chipbtn ftab ${i===bigIdx?'on':''}" data-i="${i}">${['I','II','III'][i]} · ${b.t}</button>`).join('');
  document.querySelectorAll('.ftab').forEach(b => b.onclick = () => { bigIdx = +b.dataset.i; buildBig(); });
  draw($('#bigflow'), BIG[bigIdx].src);
}

/* =================== TABELA =================== */
function buildTable(){
  $('#tbody').innerHTML = R.map(r => `<tr data-id="${r.id}" style="--fc:var(--rc-${r.id})">
    <td class="nm">${r.nome}</td><td>${r.contra}</td><td><span class="pill">${r.prazo}</span></td><td>${r.orgao}</td><td>${r.sust}</td></tr>`).join('');
  document.querySelectorAll('#tbody tr').forEach(tr => tr.onclick = () => {
    setView('mapa'); select(tr.dataset.id); $('#recursos').scrollIntoView({behavior:'smooth'});
  });
}


