function buildAssuntos(){
  $('#assu').innerHTML = ASSG.map(g => {
    const items = ASS.filter(a => a.g === g.id);
    return `<div class="lexgrp" style="--lc:var(${g.c})"><h3>${g.t}<small>${items.length} temas</small></h3><p>${g.p}</p>
      <div class="lexgrid">${items.map(a => `<details class="term assu" data-a="${a.t}">
        <summary><b>${a.t}</b><span class="lat">${a.sec}</span><span class="def">${a.d}</span></summary>
        <div class="tb"><ul>${a.pts.map(p => `<li>${p}</li>`).join('')}</ul>
        <div class="chips">${a.tags.map(t => `<span>${t}</span>`).join('')}</div></div></details>`).join('')}</div></div>`;
  }).join('');
  $('#aq').oninput = () => {
    const v = $('#aq').value.trim().toLowerCase();
    document.querySelectorAll('#assu details.assu').forEach(d => { const hit = !v || d.textContent.toLowerCase().includes(v); d.classList.toggle('hide', !hit); if (v && hit) d.open = true; });
    document.querySelectorAll('#assu .lexgrp').forEach(g => g.style.display = [...g.querySelectorAll('details.assu')].some(d => !d.classList.contains('hide')) ? '' : 'none');
  };
}

