/* ---------- fichas ---------- */
const famOff = new Set();
function cardHTML(r){
  const f = FAM[r.fam];
  return `<article class="rc" id="r-${r.id}" data-id="${r.id}" style="--fc:var(--rc-${r.id})">
    <header><div><h3>${r.nome}</h3><div class="base">${r.base}</div></div><span class="bdg">${r.badge}</span></header>
    <dl class="kv">
      <div><dt>Prazo</dt><dd>${r.prazo}</dd></div>
      <div><dt>Cabe contra</dt><dd>${r.contra}</dd></div>
      <div><dt>Órgão julgador</dt><dd>${r.orgao}</dd></div>
      <div><dt>Sustentação oral</dt><dd>${r.sust}</dd></div>
    </dl>
    <ul class="bul">${r.ess.map(x => `<li>${x}</li>`).join('')}</ul>
    <div class="atn">${r.atn}</div>
    <div class="rc-act">
      <button data-x="rot">Rotina de gabinete (${r.rot.reduce((a, g) => a + g.i.length, 0)})</button>
      <button data-x="flx">Fluxo</button>
      ${r.sc.map(s => `<button class="sc" data-rel="${s}">${scById[s].t}</button>`).join('')}
    </div>
    <div class="rc-x" hidden></div>
  </article>`;
}
function rotHTML(r){
  return r.rot.map((g, gi) => {
    const done = g.i.filter((_, ii) => state.checks[`${r.id}-${gi}-${ii}`]).length;
    return `<div class="grp"><h4>${g.t}<small>${done}/${g.i.length}</small></h4>${g.i.map((it, ii) => {
      const k = `${r.id}-${gi}-${ii}`, on = !!state.checks[k];
      return `<label class="chk ${on?'done':''}"><input type="checkbox" data-k="${k}" ${on?'checked':''}><span>${it}</span></label>`;
    }).join('')}</div>`;
  }).join('');
}
function bindCard(card){
  const r = byId[card.dataset.id], x = card.querySelector('.rc-x');
  card.querySelectorAll('[data-x]').forEach(b => b.onclick = () => {
    const was = b.classList.contains('on');
    card.querySelectorAll('[data-x]').forEach(o => o.classList.remove('on'));
    if (was){ x.hidden = true; x.innerHTML = ''; return; }
    b.classList.add('on'); x.hidden = false;
    if (b.dataset.x === 'rot'){
      x.innerHTML = rotHTML(r);
      const bindChk = () => x.querySelectorAll('input[data-k]').forEach(c => c.onchange = () => { state.checks[c.dataset.k] = c.checked; x.innerHTML = rotHTML(r); bindChk(); });
      bindChk();
    } else { x.innerHTML = '<div class="mini"></div>'; draw(x.firstChild, r.flow); }
  });
  card.querySelectorAll('[data-rel]').forEach(b => b.onclick = () => openSC(b.dataset.rel));
}
function buildRec(){
  $('#famchips').innerHTML = Object.entries(FAM).map(([k, f]) => `<button data-f="${k}" style="--fc:var(${f.c})"><i></i>${f.n} <small>${R.filter(r => r.fam === k).length}</small></button>`).join('');
  $('#recgrid').innerHTML = Object.entries(FAM).map(([k, f]) => `<section class="famsec" data-fam="${k}" id="fam-${k}" style="--fc:var(${f.c})">
      <div class="fam-h"><h2>${f.n}</h2><span>${f.s}</span></div>
      <div class="rgrid">${R.filter(r => r.fam === k).map(cardHTML).join('')}</div></section>`).join('');
  document.querySelectorAll('.rc').forEach(bindCard);
  $('#famchips').querySelectorAll('button').forEach(b => b.onclick = () => {
    const k = b.dataset.f; famOff.has(k) ? famOff.delete(k) : famOff.add(k);
    b.classList.toggle('off', famOff.has(k)); applyRecFilter();
  });
  $('#rq').oninput = applyRecFilter;
}
function applyRecFilter(){
  const v = $('#rq').value.trim().toLowerCase();
  document.querySelectorAll('.famsec').forEach(sec => {
    const off = famOff.has(sec.dataset.fam); let any = false;
    sec.querySelectorAll('.rc').forEach(c => {
      const r = byId[c.dataset.id];
      const hit = !off && (!v || (c.textContent + ' ' + r.kw).toLowerCase().includes(v));
      c.classList.toggle('hide', !hit); any = any || hit;
    });
    sec.style.display = any ? '' : 'none';
  });
}

