function buildAtl(){
  $('#atlist').innerHTML = MENU().map((s, i) => `<details class="atl-i" data-sc="${s.id}" style="--sc:var(${s.c})" ${s.id === 'spz' ? 'open' : ''}>
    <summary>${i < 10 ? `<kbd>${(i+1)%10}</kbd>` : '<span></span>'}<span><b>${s.t}</b><small>${s.s}</small></span>${SC_HOME[s.id] ? `<button class="go" data-go="${s.id}" title="Abrir no módulo">ir</button>` : '<span></span>'}</summary>
    <div class="atl-b"></div></details>`).join('');
  document.querySelectorAll('.atl-i').forEach(d => {
    const fill = () => { const b = d.querySelector('.atl-b'); if (!b.dataset.ok){ const s = scById[d.dataset.sc]; b.innerHTML = s.body(); if (s.after) s.after(b); b.dataset.ok = 1; } };
    if (d.open) fill();
    d.addEventListener('toggle', () => { if (d.open) fill(); });
  });
  document.querySelectorAll('.atl-i .go').forEach(b => b.onclick = e => { e.preventDefault(); e.stopPropagation(); const h = SC_HOME[b.dataset.go]; goTo(h[0], h[1]); });
}
openSC = function(id){
  if (!railOn()) document.body.classList.add('sheet');
  const d = document.querySelector(`.atl-i[data-sc="${id}"]`);
  if (!d){ const h = SC_HOME[id]; if (h) goTo(h[0], h[1]); return; }
  d.open = true;
  setTimeout(() => d.scrollIntoView({ behavior:'smooth', block:'start' }), 30);
}
