/* =================== V5 · PAINEL, FAVORITOS, COMPARAÇÃO =================== */

/* fluxograma textual quando a biblioteca gráfica não carrega */
function fallbackMermaid(src){
  const nodes = [], seen = new Set();
  for (const line of String(src).split('\n')){
    if (/^\s*(class|classDef|flowchart|style|linkStyle)/.test(line)) continue;
    const re = /\b([a-zA-Z][\w]*)\s*(?:\["([^"]*)"\]|\{"([^"]*)"\}|\[([^\]]+)\])/g; let m;
    while ((m = re.exec(line)) !== null){
      if (seen.has(m[1])) continue; seen.add(m[1]);
      nodes.push({ label:(m[2]||m[3]||m[4]||m[1]).replace(/<br\s*\/?\s*>/gi,' · ').replace(/<[^>]*>/g,' ').replace(/&[a-z]+;/g,' '), decision:m[3] != null });
    }
  }
  if (!nodes.length) return '<p class="err">Não foi possível apresentar o fluxograma.</p>';
  return `<div class="offline-flow-note">Leitura simplificada do fluxograma — o diagrama completo aparece quando a biblioteca gráfica pode ser carregada.</div><div class="offline-flow">${nodes.map((n, i) => `<div class="offline-flow-node ${n.decision?'decision':''}"><span>${String(i+1).padStart(2,'0')}</span><b>${escH(n.label)}</b></div>`).join('')}</div>`;
}
draw = async function(el, src){
  if (!window.mermaid){ el.innerHTML = fallbackMermaid(src); return; }
  const p = palette();
  const defs = ['org','rec','step','dec','fim'].map(k => `classDef ${k} fill:${p[k][0]},stroke:${p[k][1]},color:${p[k][2]},stroke-width:1.6px`).join('\n');
  try { const { svg } = await mermaid.render('mm' + (++mc), src + '\n' + defs); el.innerHTML = svg; }
  catch(e){ el.innerHTML = fallbackMermaid(src); }
}

/* ---------- fichas com ★, ⇄ e notas ---------- */
function toolBtns(id){
  const fav = pref.favorites.includes(id), cmp = pref.compare.includes(id);
  return `<span class="rtools"><button class="tb ${fav?'is-on':''}" data-fav="${id}" aria-pressed="${fav}" title="${fav?'Remover das fichas salvas':'Salvar ficha'}">★</button><button class="tb ${cmp?'is-on':''}" data-compare="${id}" aria-pressed="${cmp}" title="${cmp?'Retirar da comparação':'Comparar (até 3)'}">⇄</button></span>`;
}
cardHTML = function(r){
  const f = FAM[r.fam], hasNote = !!(pref.notes[r.id] || '').trim();
  return `<article class="rc" id="r-${r.id}" data-id="${r.id}" style="--fc:var(--rc-${r.id})">
    <header><div><h3>${r.nome}</h3><div class="base">${r.base}</div></div><div class="rc-hd"><span class="bdg">${r.badge}</span>${toolBtns(r.id)}</div></header>
    <dl class="kv">
      <div><dt>Prazo</dt><dd>${r.prazo}</dd></div>
      <div><dt>Cabe contra</dt><dd>${r.contra}</dd></div>
      <div><dt>Órgão julgador</dt><dd>${r.orgao}</dd></div>
      <div><dt>Sustentação oral</dt><dd>${r.sust}</dd></div>
    </dl>
    <ul class="bul">${r.ess.map(x => `<li>${x}</li>`).join('')}</ul>
    <div class="atn">${r.atn}</div>
    <div class="rc-act">
      <button data-x="rot">Rotina <small>${rotCount(r)}</small></button>
      <button data-x="flx">Fluxo</button>
      <button data-x="nota" class="${hasNote?'has':''}">Notas</button>
      ${r.sc.map(s => `<button class="sc" data-rel="${s}">${scById[s].t}</button>`).join('')}
    </div>
    <div class="rc-x" hidden></div>
  </article>`;
}
function rotCount(r){
  const tot = r.rot.reduce((a, g) => a + g.i.length, 0);
  const done = r.rot.reduce((a, g, gi) => a + g.i.filter((_, ii) => state.checks[`${r.id}-${gi}-${ii}`]).length, 0);
  return `${done}/${tot}`;
}
bindCard = function(card){
  const r = byId[card.dataset.id], x = card.querySelector('.rc-x');
  card.querySelectorAll('[data-x]').forEach(b => b.onclick = () => {
    const was = b.classList.contains('on');
    card.querySelectorAll('[data-x]').forEach(o => o.classList.remove('on'));
    if (was){ x.hidden = true; x.innerHTML = ''; return; }
    b.classList.add('on'); x.hidden = false;
    if (b.dataset.x === 'rot'){
      const paint = () => { x.innerHTML = rotHTML(r) + `<div class="rot-foot"><button class="lnk" data-clear-rot="${r.id}">Desmarcar tudo</button></div>`;
        x.querySelectorAll('input[data-k]').forEach(c => c.onchange = () => { state.checks[c.dataset.k] = c.checked; afterCheck(r); paint(); });
        x.querySelector('[data-clear-rot]').onclick = () => { Object.keys(state.checks).forEach(k => k.startsWith(r.id + '-') && delete state.checks[k]); afterCheck(r); paint(); }; };
      paint();
    } else if (b.dataset.x === 'nota'){
      x.innerHTML = `<div class="nota"><textarea data-note="${r.id}" rows="4" placeholder="Hipóteses, cuidados de minuta, precedentes da Turma…"></textarea><small>Guardadas só neste navegador; não se vinculam a processo algum.</small></div>`;
      const ta = x.querySelector('textarea'); ta.value = pref.notes[r.id] || ''; ta.focus();
    } else { x.innerHTML = '<div class="mini"></div>'; draw(x.firstChild, r.flow); }
  });
  card.querySelectorAll('[data-rel]').forEach(b => b.onclick = () => openSC(b.dataset.rel));
}
function afterCheck(r){
  persist(); refreshProgress();
  const s = document.querySelector(`#r-${r.id} [data-x="rot"] small`); if (s) s.textContent = rotCount(r);
}

/* ---------- quadro com seleção para comparar ---------- */
buildTable = function(){
  $('#tbody').innerHTML = R.map(r => `<tr data-id="${r.id}" style="--fc:var(--rc-${r.id})">
    <td class="ck"><button class="cmp-check" data-compare="${r.id}" aria-label="Comparar ${stripH(r.nome)}">＋</button></td>
    <td class="nm">${r.nome}${pref.favorites.includes(r.id) ? ' <span class="star">★</span>' : ''}</td><td>${r.contra}</td><td><span class="pill">${r.prazo}</span></td><td>${r.orgao}</td><td>${r.sust}</td></tr>`).join('');
  document.querySelectorAll('#tbody tr').forEach(tr => tr.onclick = e => {
    if (e.target.closest('[data-compare]') || e.target.closest('.cit')) return;
    setView('mapa'); select(tr.dataset.id);
  });
  refreshTools();
}

/* ---------- painel ---------- */
function buildPainel(){
  $('#actchips').innerHTML = ACTS.map(a => `<button data-act="${a.k}" title="${escH(a.d)}">${a.t}</button>`).join('');
  $('#actchips').querySelectorAll('button').forEach(b => b.onclick = () => { pref.act = b.dataset.act; persist(); refreshActs(); });
  $('#seq').innerHTML = SEQ.map((g, i) => `<div class="sq"><div class="sq-h"><i>${String(i+1).padStart(2,'0')}</i><div><b>${g.t}</b><small>${g.s}</small></div></div>
    <ul>${g.ph.map(id => { const p = PHASES.find(x => x.id === id); return p ? `<li><a href="#" data-phase="${id}"><span>${p.n}</span>${p.t}</a></li>` : ''; }).join('')}</ul></div>`).join('');
  refreshActs(); refreshFavorites(); refreshProgress(); refreshCmpCard();
}
function viaRow(id){
  const r = byId[id];
  return `<div class="via" style="--fc:var(--rc-${r.id})"><div class="via-m"><button class="via-n" data-ficha="${id}">${r.nome}</button><span class="via-p">${shortPrazo(r.prazo)}</span><small>${r.contra}</small></div>${toolBtns(id)}</div>`;
}
function refreshActs(){
  const a = ACTS.find(x => x.k === pref.act) || ACTS[0];
  $('#actchips').querySelectorAll('button').forEach(b => b.classList.toggle('on', b.dataset.act === a.k));
  $('#actd').textContent = a.d;
  $('#acthint').innerHTML = a.hint;
  $('#actres').innerHTML = a.ids.map(viaRow).join('');
}
function refreshFavorites(){
  const el = $('#pfav'); if (!el) return;
  el.innerHTML = pref.favorites.length ? pref.favorites.map(viaRow).join('')
    : '<p class="p-empty">Nenhuma ficha salva. Marque ★ nas fichas de consulta frequente e elas passam a morar aqui.</p>';
}
function refreshProgress(){
  const el = $('#pprog'); if (!el) return;
  const keys = R.flatMap(r => r.rot.flatMap((g, gi) => g.i.map((_, ii) => `${r.id}-${gi}-${ii}`)));
  const done = keys.filter(k => state.checks[k]).length, tot = keys.length;
  const rq = Object.values(reqState).filter(Boolean).length, rqt = REQ.intr.i.length + REQ.extr.i.length;
  const bar = (n, t, label, act) => `<div class="pg"><div class="pg-l"><span>${label}</span><b>${n}/${t}</b></div><div class="pg-t"><i style="width:${t ? 100*n/t : 0}%"></i></div>${act}</div>`;
  const perRec = R.map(r => { const t = r.rot.reduce((a, g) => a + g.i.length, 0), d = r.rot.reduce((a, g, gi) => a + g.i.filter((_, ii) => state.checks[`${r.id}-${gi}-${ii}`]).length, 0); return d ? `<button data-ficha="${r.id}" data-open-rot="1" style="--fc:var(--rc-${r.id})">${stripH(r.nome)} <b>${d}/${t}</b></button>` : ''; }).join('');
  el.innerHTML = bar(rq, rqt, 'Alfândega processual (requisitos)', `<a href="#" class="lnk" data-phase="chegada">abrir checklist →</a>`)
    + bar(done, tot, 'Rotinas das fichas', perRec ? `<div class="pg-recs">${perRec}</div>` : '<small class="p-empty">Nenhum item marcado ainda.</small>')
    + `<p class="p-note">Marcações guardadas apenas neste navegador — não integram o PJe.${(done || rq) ? ' <button class="lnk" id="clrAll">Zerar tudo</button>' : ''}</p>`;
  const c = $('#clrAll'); if (c) c.onclick = () => { Object.keys(state.checks).forEach(k => delete state.checks[k]); for (const k in reqState) reqState[k] = false; document.querySelectorAll('.req input').forEach(i => i.checked = false); updVerdict(); persist(); refreshProgress(); document.querySelectorAll('.rc').forEach(card => { const s = card.querySelector('[data-x="rot"] small'); if (s) s.textContent = rotCount(byId[card.dataset.id]); }); };
}
function refreshCmpCard(){
  const el = $('#pcmp'); if (!el) return;
  el.innerHTML = (pref.compare.length ? `<div class="cmp-chips">${pref.compare.map(id => `<span style="--fc:var(--rc-${id})">${stripH(byId[id].nome)}<button data-compare="${id}" aria-label="Retirar">×</button></span>`).join('')}</div>` : '<p class="p-empty">Selecione até três vias com ⇄ — nas fichas, no quadro ou acima — e confronte-as lado a lado.</p>')
    + `<div class="cmp-act"><button class="chipbtn pri" data-opencompare ${pref.compare.length ? '' : 'disabled'}>Abrir quadro comparativo</button>${pref.compare.length ? '' : ` <button class="chipbtn" data-cmp-preset="ai,ain,aresp">Sugestão: os três agravos</button>`}</div>`;
}
function refreshTools(){
  const n = pref.compare.length; $('#cmpN').textContent = n; $('#cmpBtn').classList.toggle('has', n > 0);
  document.querySelectorAll('[data-compare]').forEach(b => { const on = pref.compare.includes(b.dataset.compare); b.classList.toggle('is-on', on); b.setAttribute('aria-pressed', on); if (b.classList.contains('cmp-check')) b.textContent = on ? '✓' : '＋'; });
  document.querySelectorAll('[data-fav]').forEach(b => { const on = pref.favorites.includes(b.dataset.fav); b.classList.toggle('is-on', on); b.setAttribute('aria-pressed', on); });
  document.querySelectorAll('#index a[data-target^="r-"]').forEach(a => a.classList.toggle('fav', pref.favorites.includes(a.dataset.target.slice(2))));
}
function toggleFavorite(id){ const i = pref.favorites.indexOf(id); i >= 0 ? pref.favorites.splice(i, 1) : pref.favorites.push(id); persist(); refreshFavorites(); refreshActs(); refreshTools(); }
let cmpMsgT;
function toggleCompare(id){
  const i = pref.compare.indexOf(id);
  if (i >= 0) pref.compare.splice(i, 1);
  else if (pref.compare.length < 3) pref.compare.push(id);
  else { toast('Comparação cheia: retire uma das três vias antes de incluir outra.'); openCompare(); return; }
  persist(); refreshActs(); refreshFavorites(); refreshCmpCard(); refreshTools(); if ($('#cmpDlg').open) renderCompare();
}
function toast(msg){ const t = $('#toast'); t.textContent = msg; t.hidden = false; clearTimeout(cmpMsgT); cmpMsgT = setTimeout(() => t.hidden = true, 2600); }

/* ---------- comparação ---------- */
const CMP_ROWS = [['Família', r => FAM[r.fam].n], ['Prazo', r => r.prazo], ['Cabe contra', r => r.contra], ['Órgão julgador', r => r.orgao], ['Sustentação oral', r => r.sust], ['Base normativa', r => r.base], ['Pontos-chave', r => '<ul>' + r.ess.map(x => '<li>' + x + '</li>').join('') + '</ul>'], ['Atenção', r => r.atn]];
function renderCompare(){
  const cols = pref.compare.map(id => byId[id]);
  $('#cmpBody').innerHTML = !cols.length ? '<p class="p-empty">Nenhuma via selecionada. Use ⇄ nas fichas, no quadro ou no painel.</p>'
    : `<table class="cmp-t" style="--n:${cols.length}"><thead><tr><th></th>${cols.map(r => `<th style="--fc:var(--rc-${r.id})"><b>${r.nome}</b><span><button data-ficha="${r.id}">ficha ↗</button><button data-compare="${r.id}">retirar ×</button></span></th>`).join('')}</tr></thead>
       <tbody>${CMP_ROWS.map(([k, fn]) => `<tr><th>${k}</th>${cols.map(r => `<td>${fn(r)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
  $('#cmpCopy').disabled = $('#cmpClear').disabled = !cols.length;
}
function openCompare(){ renderCompare(); const d = $('#cmpDlg'); if (!d.open) d.showModal(); }
function compareText(){
  return ['QUADRO COMPARATIVO · VIAS RECURSAIS', ...pref.compare.map(id => { const r = byId[id];
    return '\n' + stripH(r.nome).toUpperCase() + '\n' + CMP_ROWS.slice(0, 6).map(([k, fn]) => k + ': ' + stripH(fn(r))).join('\n') + '\nPontos-chave:\n- ' + r.ess.map(stripH).join('\n- '); })].join('\n');
}

/* ---------- índice do painel ---------- */
function addPainelIndex(){
  const g = document.createElement('div'); g.className = 'ix-g'; g.dataset.tab = 'painel';
  g.innerHTML = `<button>Central</button><ul>${[['p-ato','Ato → via cabível'],['p-seq','Sequência do gabinete'],['p-tar','Tarefas do PJe'],['p-comp','Competência e impedimentos'],['p-rec','Prazos recursais'],['p-lex','Léxico recursal'],['p-rit','Regimento Interno'],['p-fav','Fichas salvas'],['p-prog','Conferências'],['p-cmp','Comparação']].map(([id, t]) => `<li><a href="#" data-target="${id}"><i></i>${t}</a></li>`).join('')}</ul>`;
  $('#index').prepend(g);
  g.querySelector(':scope > button').onclick = () => scrollTo({ top:0, behavior:'smooth' });
  g.querySelectorAll('a').forEach(a => a.onclick = e => { e.preventDefault(); goTo('painel', a.dataset.target); });
}

/* ---------- eventos ---------- */
document.addEventListener('click', e => {
  const t = e.target.closest && e.target; if (!t) return;
  const fav = t.closest('[data-fav]'); if (fav){ e.preventDefault(); e.stopPropagation(); toggleFavorite(fav.dataset.fav); return; }
  const cmp = t.closest('[data-compare]'); if (cmp){ e.preventDefault(); e.stopPropagation(); toggleCompare(cmp.dataset.compare); return; }
  const pre = t.closest('[data-cmp-preset]'); if (pre){ e.preventDefault(); pref.compare = pre.dataset.cmpPreset.split(','); persist(); refreshCmpCard(); refreshTools(); refreshActs(); openCompare(); return; }
  if (t.closest('[data-opencompare]')){ e.preventDefault(); openCompare(); return; }
  const fi = t.closest('[data-ficha]'); if (fi){ e.preventDefault(); if ($('#cmpDlg').open) $('#cmpDlg').close(); goFicha(fi.dataset.ficha);
    if (fi.dataset.openRot) setTimeout(() => { const b = document.querySelector(`#r-${fi.dataset.ficha} [data-x="rot"]`); b && !b.classList.contains('on') && b.click(); }, 120); return; }
  const ph = t.closest('[data-phase]'); if (ph){ e.preventDefault(); goRot(ph.dataset.phase); return; }
});
let noteT;
document.addEventListener('input', e => {
  const n = e.target.closest && e.target.closest('[data-note]'); if (!n) return;
  clearTimeout(noteT); noteT = setTimeout(() => { pref.notes[n.dataset.note] = n.value; persist();
    const b = document.querySelector(`#r-${n.dataset.note} [data-x="nota"]`); b && b.classList.toggle('has', !!n.value.trim()); }, 250);
});
document.addEventListener('change', e => { if (e.target.matches && e.target.matches('.req input')) setTimeout(() => { persist(); refreshProgress(); }, 0); });
$('#cmpBtn').onclick = openCompare;
$('#cmpClose').onclick = () => $('#cmpDlg').close();
$('#cmpDlg').addEventListener('click', e => { if (e.target === $('#cmpDlg')) $('#cmpDlg').close(); });
$('#cmpClear').onclick = () => { pref.compare = []; persist(); refreshCmpCard(); refreshTools(); refreshActs(); renderCompare(); };
$('#cmpCopy').onclick = async () => {
  const txt = compareText(), b = $('#cmpCopy');
  try { await navigator.clipboard.writeText(txt); } catch(err){ const ta = document.createElement('textarea'); ta.value = txt; document.body.append(ta); ta.select(); try { document.execCommand('copy'); } catch(e2){} ta.remove(); }
  b.textContent = '✓ Copiado'; setTimeout(() => b.textContent = 'Copiar como texto', 1600);
};
document.addEventListener('keydown', e => {
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k'){ e.preventDefault(); openPal(); }
});
$('#themeBtn').addEventListener('click', () => { pref.theme = root.dataset.theme; persist(); });

/* ---------- arranque ---------- */
if (pref.theme === 'light' || pref.theme === 'dark'){ root.dataset.theme = pref.theme; rerender(); }
else root.dataset.theme = 'light';
Object.assign(reqState, pref.req);
document.querySelectorAll('.req input').forEach(c => c.checked = !!reqState[c.dataset.k]);
if ($('#vres')) updVerdict();
addPainelIndex();
buildPainel();
refreshTools();
showTab(commandTabFromLocation());

