function tkAtosHTML(id, open){
  const a = TKATOS[id]; if (!a || !a.length) return '';
  const kinds = [...new Set(a.map(x => x[0]))];
  return `<details class="tk-atos"${open ? ' open' : ''}><summary>Atos possíveis <span>${a.length}</span>${kinds.map(k => `<i style="--ac:var(${ATK[k].c})">${ATK[k].t}</i>`).join('')}</summary>
    <ul>${a.map(([k, t, b]) => `<li style="--ac:var(${ATK[k].c})"><em>${ATK[k].t}</em><span>${t}${b ? `<small>${b}</small>` : ''}</span></li>`).join('')}</ul></details>`;
}

const stById = Object.fromEntries(STN.map(x => [x.id, x]));
pref.pje = pref.pje && typeof pref.pje === 'object' ? pref.pje : {};
pref.pjeImp = pref.pjeImp && typeof pref.pjeImp === 'object' && pref.pjeImp.c ? pref.pjeImp : null;
function pjeKey(s){ return String(s).toLowerCase().replace(/\s*[-–—]\s*/g, ' - ').replace(/\s+/g, ' ').trim(); }
const tkBase = t => (pref.pjeImp && pref.pjeImp.c[pjeKey(t.nome)]) || 0;
const tkLoaded = () => !!(pref.pjeImp || Object.keys(pref.pje).length);
const tkN = t => { const v = pref.pje[t.id]; return (v !== undefined && v !== '' && Number.isFinite(+v)) ? Math.max(0, Math.round(+v)) : tkBase(t); };
const tkTot = () => TK.reduce((a, t) => a + tkN(t), 0);
const stTot = id => TK.filter(t => t.st === id).reduce((a, t) => a + tkN(t), 0);
const pcT = (a, b) => b ? Math.round(100 * a / b) : 0;
const fmtN = n => tkLoaded() ? Number(n).toLocaleString('pt-BR') : '—';
let tkEditing = false; const tkOff = new Set();

const TKFLOW = `flowchart TD
U["Recebidos da unidade<br/>processante"] --> T["Triagem de Gabinete"]
T --> D{"Analisar tipo de<br/>decisão a proferir"}
D -->|Art. 932| M["Minutar ato judicial"]
M --> R["Revisar ato judicial"]
R --> A["Assinar ato judicial"]
D -->|Colegiado| P["[Sessão] Preparar<br/>relatório e voto"]
D -->|Tema pendente| S["Sobrestados<br/>STF · STJ · IRDR · IAC"]
S -->|Tese julgada| D
P --> AP["[Sessão] Aptos<br/>para julgamento"]
AP --> AG["[Sessão] Aguardando<br/>a sessão"]
AG -->|Vista · adiamento| RA["[Sessão] Retirados<br/>e adiados"]
RA --> AG
AG --> IT["[Sessão] Confirmar<br/>Inteiro Teor"]
E["Recebidos com<br/>Embargos de Declaração"] --> X{"Ato embargado"}
A -.->|ED · Ag. Int| I["[ED] · [Ag. Int]<br/>minutar e assinar"]
IT -.->|ED contra acórdão| E
X -->|Monocrática| I
X -->|Acórdão| SE["[Sessão – ED]<br/>relatório, voto e mesa"]
class U,E org
class T,M,R,P,AP,AG,RA,I,SE step
class S rec
class D,X dec
class A,IT fim`;

function tkLinks(t){
  return t.l.map(x => {
    if (x.rot){ const p = PHASES.find(q => q.id === x.rot); return p ? `<button data-phase="${x.rot}">Rotina · ${p.t}</button>` : ''; }
    if (x.sc && scById[x.sc]) return `<button data-tksc="${x.sc}">✦ ${scById[x.sc].t}</button>`;
    if (x.ficha && byId[x.ficha]) return `<button data-ficha="${x.ficha}">Ficha · ${stripH(byId[x.ficha].nome)}</button>`;
    if (x.tk && tkById[x.tk]) return `<button data-tk="${x.tk}">→ ${tkById[x.tk].nome}</button>`;
    return '';
  }).join('');
}
function tkCard(t, mx){
  const s = stById[t.st], n = tkN(t);
  return `<article class="tk" id="tk-${t.id}" data-id="${t.id}" style="--fc:var(${s.c})">
    <header><div><code class="pje">${t.nome}</code>${t.tag ? `<span class="tk-tag">${t.tag}</span>` : ''}</div>
      <span class="tk-n">${tkEditing ? `<input type="number" min="0" step="1" inputmode="numeric" data-tkn="${t.id}" value="${n}" aria-label="Quantidade em ${escH(t.nome)}">` : fmtN(n)}</span></header>
    ${PJEF_OF && PJEF_OF[pjeNorm(t.nome)] ? `<div class="tk-fl">Fluxo PJe · ${escH(PJEF_OF[pjeNorm(t.nome)])}</div>` : ""}
    <div class="tk-bar"><i style="width:${mx ? 100 * n / mx : 0}%"></i></div>
    <p>${t.serve}</p>
    <div class="tk-g"><b>No gabinete ·</b> ${t.gab}</div>
    ${tkAtosHTML(t.id)}
    ${t.l.length ? `<div class="tk-l">${tkLinks(t)}</div>` : ''}
  </article>`;
}
function tkSummary(){
  if (!tkLoaded()){
    $('#tksum').innerHTML = '<div class="tk-k" style="--fc:var(--m-pje)"><span>Acervo</span><b>—</b><i>sem relatório</i></div>';
    document.getElementById('tkimp').classList.add('is-empty');
    $('#tkstack').innerHTML = '';
    $('#tkleg').innerHTML = STN.map(s => `<button data-st="${s.id}" style="--fc:var(${s.c})"><i></i>${s.t}</button>`).join('');
    $('#tkleg').querySelectorAll('[data-st]').forEach(b => b.onclick = () => { const el = document.getElementById('st-' + b.dataset.st); el && el.scrollIntoView({ behavior:'smooth', block:'start' }); });
    $('#tkdate').textContent = 'Importe o relatório do PJe para ver quantos processos há em cada caixa.';
    $('#tkread').innerHTML = '<div style="--fc:var(--m-pje)"><b class="h">Aguardando os números</b>Gargalos, pendências de triagem, petições em sobrestados e fluxo da pauta são calculados a partir do relatório importado.</div>';
    return;
  }
  document.getElementById('tkimp').classList.remove('is-empty');
  const T = tkTot(), g = id => tkN(tkById[id]);
  const ent = stTot('entrada'), ses = stTot('sessao') + stTot('sed'), sob = stTot('sobr');
  $('#tksum').innerHTML = [
    ['Acervo nas caixas', T, `${TK.length} tarefas · 6 estações`, '--m-pje'],
    ['Entrada e triagem', ent, pcT(ent, T) + '% do acervo', '--navy'],
    ['Rumo ao colegiado', ses, pcT(ses, T) + '% do acervo', '--green'],
    ['Suspensos', sob, pcT(sob, T) + '% do acervo', '--plum']
  ].map(([k, v, i, c]) => `<div class="tk-k" style="--fc:var(${c})"><span>${k}</span><b>${fmtN(v)}</b><i>${i}</i></div>`).join('');
  $('#tkstack').innerHTML = STN.map(s => `<i style="--fc:var(${s.c});width:${T ? 100 * stTot(s.id) / T : 0}%" title="${s.t}: ${fmtN(stTot(s.id))}"></i>`).join('');
  $('#tkleg').innerHTML = STN.map(s => `<button data-st="${s.id}" style="--fc:var(${s.c})"><i></i>${s.t} <b>${fmtN(stTot(s.id))}</b></button>`).join('');
  $('#tkleg').querySelectorAll('[data-st]').forEach(b => b.onclick = () => { const el = document.getElementById('st-' + b.dataset.st); el && el.scrollIntoView({ behavior:'smooth', block:'start' }); });
  const imp = pref.pjeImp, man = Object.keys(pref.pje).length;
  $('#tkdate').textContent = (imp ? `Relatório ${imp.src}${imp.d ? ' de ' + imp.d.slice(0, 10) : ''} · ${fmtN(imp.procs)} processos distintos` : 'Contagens digitadas à mão')
    + (imp && man ? ` · ${man} ${man === 1 ? 'caixa ajustada' : 'caixas ajustadas'} à mão` : '');
  const top = [...TK].sort((a, b) => tkN(b) - tkN(a))[0];
  const pend = g('triagem') + g('analisar'), pet = g('sob_pet') + g('su_pet');
  const ag = g('s_aguard'), ret = g('s_ret'), rr = pcT(ret, ag + ret);
  $('#tkread').innerHTML = [
    ['--green', 'Onde o rio se estreita', `<b>${top.nome}</b> concentra ${fmtN(tkN(top))} processos — ${pcT(tkN(top), T)}% de tudo o que está nas caixas.`],
    ['--navy', 'Acervo à espera de rumo', `${fmtN(pend)} processos entre a triagem e a análise do tipo de decisão. Uma triagem em lote por assunto e tema pode mandar parte deles direto à via monocrática.`],
    ['--plum', 'Sobrestados com petição', `${fmtN(pet)} petições aguardam exame em processos suspensos. A notícia de que o tema foi julgado é o sinal para retomar o curso.`],
    ['--gold', 'Fluxo da pauta', `${fmtN(ag)} processos pautados e ${fmtN(ret)} retirados ou adiados (${rr}%). ${rr < 10 ? 'A pauta não parece ser o ponto de estrangulamento.' : 'Vale examinar os motivos das retiradas.'}`]
  ].map(([c, h, t]) => `<div style="--fc:var(${c})"><b class="h">${h}</b>${t}</div>`).join('');
}
function tkList(){
  const mx = Math.max(1, ...TK.map(tkN)), T = tkTot();
  $('#tklist').innerHTML = STN.map(s => {
    const its = TK.filter(t => t.st === s.id), st = stTot(s.id);
    return `<section class="tkst" data-st="${s.id}" style="--fc:var(${s.c})">
      <div class="st-h" id="st-${s.id}"><h3>${s.t}</h3><span class="st-n">${fmtN(st)}</span><small>${its.length} caixas${tkLoaded() ? ' · ' + pcT(st, T) + '% do acervo' : ''}</small></div>
      <p class="st-d">${s.d}</p>${s.note ? `<div class="tk-note">${s.note}</div>` : ''}
      <div class="tkgrid">${its.map(t => tkCard(t, mx)).join('')}</div></section>`;
  }).join('') + (typeof pjeExtraHTML === 'function' ? pjeExtraHTML() : '');
  $('#tklist').querySelectorAll('input[data-tkn]').forEach(inp => inp.onchange = () => {
    const t = tkById[inp.dataset.tkn], v = inp.value.trim();
    if (v === '' || +v === tkBase(t)) delete pref.pje[t.id]; else pref.pje[t.id] = Math.max(0, Math.round(+v));
    pref.pjeDate = Object.keys(pref.pje).length ? new Date().toLocaleDateString('pt-BR') : null;
    persist(); tkSummary(); tkResetBtn(); if (typeof buildFluxosPJe === 'function') buildFluxosPJe(); $('#tkClear').hidden = !tkLoaded();
  });
  tkFilter();
}
function tkFilter(){
  const v = $('#tkq').value.trim().toLowerCase();
  document.querySelectorAll('#tklist .tkst').forEach(sec => {
    const off = tkOff.has(sec.dataset.st); let any = false;
    sec.querySelectorAll('.tk').forEach(c => { const hit = !off && (!v || c.textContent.toLowerCase().includes(v)); c.classList.toggle('hide', !hit); any = any || hit; });
    sec.style.display = any ? '' : 'none';
  });
}
function tkResetBtn(){ $('#tkReset').hidden = !Object.keys(pref.pje).length; }
function goTask(id){
  showTab('tarefas'); $('#tkq').value = ''; tkOff.clear();
  $('#tkchips').querySelectorAll('button').forEach(b => b.classList.remove('off')); tkFilter();
  setTimeout(() => { const el = document.getElementById('tk-' + id); if (!el) return;
    el.scrollIntoView({ behavior:'smooth', block:'center' }); el.classList.add('flash'); setTimeout(() => el.classList.remove('flash'), 1400); }, 40);
}
function buildTarefas(){
  $('#tkchips').innerHTML = STN.map(s => `<button data-f="${s.id}" style="--fc:var(${s.c})"><i></i>${s.t}</button>`).join('') + '<button data-f="x" style="--fc:var(--muted)"><i></i>Demais caixas do PJe</button>';
  $('#tkchips').querySelectorAll('button').forEach(b => b.onclick = () => {
    const k = b.dataset.f; tkOff.has(k) ? tkOff.delete(k) : tkOff.add(k); b.classList.toggle('off', tkOff.has(k)); tkFilter();
  });
  $('#tkq').oninput = tkFilter;
  $('#tkEdit').onclick = () => { tkEditing = !tkEditing; $('#tkEdit').textContent = tkEditing ? 'Concluir' : 'Ajustar à mão'; $('#tkEdit').classList.toggle('on', tkEditing); tkList();
    if (tkEditing){ const f = $('#tklist input[data-tkn]'); f && f.focus(); } };
  $('#tkReset').onclick = () => { pref.pje = {}; pref.pjeDate = null; persist(); tkSummary(); tkList(); tkResetBtn(); if (typeof buildFluxosPJe === 'function') buildFluxosPJe(); };
  tkSummary(); tkList(); tkResetBtn();
  /* índice lateral */
  const g = document.createElement('div'); g.className = 'ix-g'; g.dataset.tab = 'tarefas';
  g.innerHTML = `<button>Tarefas PJe</button><ul>${[['tk-panorama','Panorama do acervo'],['tk-mapa','Fluxograma interativo'],['tk-leitura','Leitura do acervo'],['tk-caixas','As caixas, uma a uma']].map(([id, t]) => `<li><a href="#" data-target="${id}"><i></i>${t}</a></li>`).join('')}${STN.map(s => `<li class="ixs"><a href="#" data-target="st-${s.id}" style="--fc:var(${s.c})"><i></i>${s.t}</a></li>`).join('')}</ul>`;
  const rot = document.querySelector('#index .ix-g[data-tab="rotina"]'); rot ? rot.after(g) : $('#index').append(g);
  g.querySelector(':scope > button').onclick = () => scrollTo({ top:0, behavior:'smooth' });
  g.querySelectorAll('a').forEach(a => a.onclick = e => { e.preventDefault(); goTo('tarefas', a.dataset.target); });
  /* busca global */
  IDX.push(...TK.map(t => ({ k:'Tarefa PJe', t:t.nome, s:stripH(t.serve), txt:[t.nome, t.serve, t.gab, stById[t.st].t].join(' '), go:() => goTask(t.id) }))
    .map(i => ({ ...i, low:stripH(i.txt).toLowerCase() })));
}
document.addEventListener('click', e => {
  const t = e.target.closest && e.target; if (!t) return;
  const s = t.closest('[data-tksc]'); if (s){ e.preventDefault(); openSC(s.dataset.tksc); return; }
  const k = t.closest('[data-tk]'); if (k){ e.preventDefault(); goTask(k.dataset.tk); }
});
const tkRedraw = () => {};
$('#themeBtn').addEventListener('click', tkRedraw);
matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => { if (!root.dataset.theme) tkRedraw(); });

