const ritKey = n => String(n).replace(/\./g, '').replace(/[º°]/g, '').replace(/-/g, '').toUpperCase();
const RITA = {}, RITTXT = {};
RIT_DOC.forEach(n => { if (n.b){ RITA[n.n] = n; RITTXT[n.n] = n.b.filter(b => b[0] !== 'n').map(b => b[1]).join('\n'); } });
const ritLabel = k => { const m = String(k).match(/^(\d+)([A-Z]?)$/); if (!m) return k; return m[1] + (+m[1] < 10 && !m[2] ? 'º' : '') + (m[2] ? '-' + m[2] : ''); };
const ritStrip = s => s.replace(/^Art\.\s*\d+(?:º|°)?(?:-?[A-Z](?=[\s.\-–]))?\s*[-–.]?\s*/, '');
const RIT_KEY_ARTS = [
  ['15','Prevenção do Relator','A Turma que primeiro conhece do feito tem o Relator prevento para incidentes e recursos.'],
  ['33','Atribuições do Relator','XII e XIII: monocráticas do art. 932 do CPC · XV: tutela no agravo · XVIII: agravos de suas decisões.'],
  ['64','Anotações na autuação','Recurso adesivo, réu preso, impedimentos e prevenção.'],
  ['10','Competência das Seções','A matéria define a Seção e as Turmas que a integram.'],
  ['24','Presidente de Turma','Preside as sessões, manda incluir em pauta, assina ofícios executórios.'],
  ['103','Assunção de competência','IAC — arts. 103 a 106.'],
  ['106A','IRDR','Do pedido à aplicação da tese — arts. 106-A a 106-J.'],
  ['133A','Sessões virtuais','Julgamento em ambiente eletrônico, não presencial.'],
  ['143','Sustentação oral','Cabimento (I a X) e vedações (parágrafo único).'],
  ['171','Inconstitucionalidade','Arguição e reserva de plenário — arts. 171 a 177.'],
  ['247','Recursos internos','Quadro dos recursos contra decisões do Órgão Especial, Seções, Turmas e Relatores.'],
  ['251','Agravo regimental','Reconsideração pelo prolator; empate mantém a decisão.'],
  ['260','Julgamento não unânime','Nas Turmas, prosseguimento com mais dois votos (CPC, art. 942).'],
  ['262','Embargos de declaração','Cabimento, prazo e negativa de seguimento — arts. 262 a 264.'],
  ['277','REsp e RE','Interpostos na Vice-Presidência, em petições distintas.'],
  ['279','Suspensão de liminar','Lei 8.437/1992, art. 4º, e Lei 12.016/2009, art. 15.'],
  ['298','Tutela provisória','Pedido ao Relator; efeito suspensivo em REsp/RE na Vice-Presidência (§ 3º).'],
  ['355','Precatórios e RPV','Requisições de pagamento — arts. 355 a 358.'],
  ['368','Gabinete do Desembargador','Estrutura e atribuições — arts. 368 a 371.']
];
const RIT_ASS = [
  { n:'1/1999', pub:'DJ de 22.03.2000', ref:'art. 11, II, “n”', t:'Cabe ao Corregedor-Geral da Justiça Federal da Terceira Região “colher subsídios e prestar todas as informações necessárias sobre candidato a promoção.”' },
  { n:'2/1999', pub:'DJ de 22.03.2000', ref:'art. 11, I', t:'Cabe ao Plenário “propor a alteração do número de membros do Tribunal.”' },
  { n:'3/2000', pub:'DJ de 30.11.2000', ref:'art. 26', t:'“A expressão membros do Tribunal se refere à composição integral do Tribunal.”' },
  { n:'4/2003', pub:'DJ de 07.07.2003', ref:'arts. 5º, parágrafo único, e 7º', t:'Compete ao Plenário eleger os membros do Conselho de Administração e do Conselho da Justiça Federal da 3ª Região; o Conselho de Administração deve, sempre que possível, preservar a paridade representativa entre as Seções.' }
];
/* árvore com intervalos de artigos */
const RIT_TREE = (() => {
  const root = { h:-1, kids:[], arts:[] }, stack = [root];
  RIT_DOC.forEach(n => {
    if (n.h !== undefined){
      while (stack.length > 1 && stack[stack.length - 1].h >= n.h) stack.pop();
      const node = { ...n, kids:[], arts:[], all:[] };
      stack[stack.length - 1].kids.push(node); stack.push(node);
    } else {
      stack[stack.length - 1].arts.push(n.n);
      stack.forEach(s => s.all && s.all.push(n.n));
    }
  });
  let seq = 0; const walk = n => { n.id = 'rh' + (seq++); n.kids.forEach(walk); }; root.kids.forEach(walk);
  return root;
})();
const ritRange = a => !a.length ? '' : a.length === 1 ? 'art. ' + ritLabel(a[0]) : 'arts. ' + ritLabel(a[0]) + ' a ' + ritLabel(a[a.length - 1]);
let ritCitedSet = null;
const ritState = { notes:false, cited:false, q:'' };

function ritLinkText(txt){
  return escH(txt).replace(/\b(arts?\.|artigos?)(\s+)(\d+)(º|°)?(-?[A-Z](?![a-zà-úA-Z]))?/g, (m, w, sp, num, o, suf, off, str) => {
    const key = num + (suf ? suf.replace('-', '') : '');
    const tail = str.slice(off + m.length, off + m.length + 80);
    if (!RITA[key] || /^[^;]{0,50}?\b(d[aoe]s?|na|no|pela|pelo)\s+(Lei|Código|CPC|CPP|Constituição|Decreto|Resolução|Regimento Interno do S|Medida Provisória|MP|Emenda Constitucional|LC)\b/.test(tail)) return m;
    return `${w}${sp}<span class="cit rl" tabindex="0" data-ritk="${key}">${num}${o || ''}${suf || ''}</span>`;
  });
}
function ritArt(a){
  const lab = 'Art. ' + ritLabel(a.n);
  const bl = a.b.map((b, i) => {
    const txt = i === 0 ? ritStrip(b[1]) : b[1];
    return `<p class="rb ${b[0]}">${ritLinkText(txt)}</p>`;
  }).join('');
  return `<article class="ra${a.rev ? ' rev' : ''}" id="ra-${a.n}" data-n="${a.n}">
    <header><button class="ra-n" data-ritgo="${a.n}" title="Fixar endereço deste artigo">${lab}</button>${a.rev ? '<span class="ra-tag">revogado</span>' : ''}<span class="ra-cited" hidden>citado na Central</span>
      <button class="ra-cp" data-ritcp="${a.n}" title="Copiar o texto do artigo">copiar</button></header>
    <div class="ra-b">${bl}</div></article>`;
}
function ritHeadHTML(n){
  const nt = n.nt && n.nt.length ? `<div class="rh-nt">${n.nt.map(escH).join('<br>')}</div>` : '';
  const arts = n.arts.map(k => ritArt(RITA[k])).join('');
  const kids = n.kids.map(ritHeadHTML).join('');
  const meta = `<small>${ritRange(n.all)} · ${n.all.length} ${n.all.length === 1 ? 'artigo' : 'artigos'}</small>`;
  if (n.h === 0) return `<section class="rp" id="${n.id}"><div class="rp-h"><span>${n.k}</span><b>${escH(n.t)}</b>${meta}</div>${nt}${arts}${kids}</section>`;
  if (n.h === 1) return `<details class="rt" id="${n.id}"><summary><span class="rt-k">${n.k}</span><b>${escH(n.t)}</b>${meta}</summary><div class="rt-b">${nt}${arts}${kids}</div></details>`;
  const H = n.h === 2 ? 'h4' : 'h5';
  return `<section class="rs l${n.h}" id="${n.id}"><${H} class="rs-h"><span>${n.k}</span> ${escH(n.t)} ${meta}</${H}>${nt}${arts}${kids}</section>`;
}
function ritMapHTML(){
  return `<div class="rmap">${RIT_TREE.kids.map(p => `<div class="rm-p" style="--rc:var(--m-rit)">
      <button class="rm-ph" data-rith="${p.id}"><span>${p.k}</span><b>${escH(p.t.charAt(0) + p.t.slice(1).toLowerCase())}</b><small>${ritRange(p.all)}</small></button>
      ${p.kids.map(t => `<div class="rm-t"><button class="rm-th" data-rith="${t.id}"><span>${t.k.replace('Título ', 'T. ')}</span><b>${escH(t.t)}</b><small>${ritRange(t.all)}</small></button>
        ${t.kids.length ? `<div class="rm-c">${t.kids.map(c => `<button data-rith="${c.id}" title="${escH(c.k + ' — ' + c.t)} · ${ritRange(c.all)}">${escH(c.t)}</button>`).join('')}</div>` : ''}</div>`).join('')}
    </div>`).join('')}</div>`;
}
function ritOpenTo(el){
  for (let p = el; p; p = p.parentElement) if (p.tagName === 'DETAILS') p.open = true;
}
function ritGo(k, sub){
  const key = ritKey(k);
  if ($('#cmpDlg') && $('#cmpDlg').open) $('#cmpDlg').close();
  if (typeof hidePop === 'function') hidePop(true);
  showTab('regimento');
  if (ritState.q || ritState.cited){ $('#ritq').value = ''; ritState.q = ''; ritState.cited = false; $('#ritCited').classList.remove('on'); ritFilter(); }
  const el = document.getElementById('ra-' + key); if (!el) return;
  ritOpenTo(el);
  setTimeout(() => { el.scrollIntoView({ behavior:'smooth', block:'start' }); el.classList.add('flash'); setTimeout(() => el.classList.remove('flash'), 1600); }, 40);
}
function ritGoHead(id){
  showTab('regimento');
  const el = document.getElementById(id); if (!el) return;
  ritOpenTo(el); if (el.tagName === 'DETAILS') el.open = true;
  setTimeout(() => el.scrollIntoView({ behavior:'smooth', block:'start' }), 40);
}
function ritCited(){
  if (ritCitedSet) return ritCitedSet;
  const txt = [...document.querySelectorAll('.tabpane:not(#regimento), #rail')].map(e => e.textContent).join('\n')
    + JSON.stringify(R) + JSON.stringify(LEX) + JSON.stringify(ASS) + SC.map(s => { try { return s.body(); } catch(e){ return ''; } }).join(' ');
  ritCitedSet = new Set();
  findCites(stripH(txt)).forEach(h => h.items.forEach(i => { if (i.k === 'ART' && i.code === 'RIT' && RITA[ritKey(i.n)]) ritCitedSet.add(ritKey(i.n)); }));
  const re = /RITRF3[^.;\n]{0,80}/g; let m;
  while ((m = re.exec(stripH(txt)))) [...m[0].matchAll(/\b(\d{1,3}(?:-[A-Z])?)\b/g)].forEach(x => { const k = ritKey(x[1]); if (RITA[k] && +x[1].match(/\d+/)[0] <= 382) ritCitedSet.add(k); });
  return ritCitedSet;
}
function ritFilter(){
  const q = ritState.q.trim().toLowerCase(), cited = ritState.cited ? ritCited() : null;
  const num = q.replace(/^art(igo)?s?\.?\s*/, '').replace(/[º°\s]/g, '');
  const byNum = /^\d+[a-z]?$/i.test(num) ? ritKey(num) : null;
  let shown = 0;
  document.querySelectorAll('#ritdoc .ra').forEach(a => {
    const k = a.dataset.n;
    let hit = true;
    if (q) hit = byNum ? k === byNum : (RITTXT[k] || '').toLowerCase().includes(q) || a.textContent.toLowerCase().includes(q);
    if (hit && cited) hit = cited.has(k);
    a.classList.toggle('hide', !hit); if (hit) shown++;
  });
  const filtering = !!(q || cited);
  document.querySelectorAll('#ritdoc .rs, #ritdoc .rt, #ritdoc .rp').forEach(s => {
    const any = !!s.querySelector('.ra:not(.hide)');
    s.classList.toggle('hide', filtering && !any);
    if (filtering && any && s.tagName === 'DETAILS') s.open = true;
  });
  $('#ritcount').textContent = filtering ? `${shown} ${shown === 1 ? 'artigo' : 'artigos'}` : `${Object.keys(RITA).length} artigos`;
}
function buildRegimento(){
  $('#ritmap').innerHTML = ritMapHTML();
  $('#ritkey').innerHTML = RIT_KEY_ARTS.map(([k, t, d]) => `<button class="rk" data-ritgo="${k}"><span>Art. ${ritLabel(k)}</span><b>${t}</b><small>${d}</small></button>`).join('');
  $('#ritdoc').innerHTML = RIT_TREE.kids.map(ritHeadHTML).join('');
  $('#ritass').innerHTML = RIT_ASS.map(a => `<div class="card ras"><div class="ras-h"><b>Assento Regimental nº ${a.n}</b><small>${a.pub} · interpreta o ${a.ref}</small></div><p>${ritLinkText(a.t)}</p></div>`).join('');
  document.querySelectorAll('#regimento .rl').forEach(s => s._items = [{ k:'ART', code:'RIT', n:ritLabel(s.dataset.ritk), q:'' }]);
  $('#ritq').addEventListener('input', () => { ritState.q = $('#ritq').value; ritFilter(); });
  $('#ritNotes').onclick = () => { ritState.notes = !ritState.notes; $('#ritdoc').classList.toggle('shownotes', ritState.notes); $('#ritNotes').classList.toggle('on', ritState.notes); };
  $('#ritCited').onclick = () => {
    ritState.cited = !ritState.cited; $('#ritCited').classList.toggle('on', ritState.cited);
    const set = ritCited(); document.querySelectorAll('#ritdoc .ra').forEach(a => a.querySelector('.ra-cited').hidden = !set.has(a.dataset.n));
    ritFilter();
  };
  $('#ritOpen').onclick = () => document.querySelectorAll('#ritdoc details.rt:not(.hide)').forEach(d => d.open = true);
  $('#ritClose').onclick = () => document.querySelectorAll('#ritdoc details.rt').forEach(d => d.open = false);
  $('#regimento').addEventListener('click', e => {
    const t = e.target.closest && e.target; if (!t) return;
    const h = t.closest('[data-rith]'); if (h){ e.preventDefault(); ritGoHead(h.dataset.rith); return; }
    const c = t.closest('[data-ritcp]'); if (c){
      e.preventDefault(); const k = c.dataset.ritcp, txt = RITTXT[k] + '\n(RITRF3, art. ' + ritLabel(k) + ')';
      const done = () => { c.textContent = 'copiado ✓'; setTimeout(() => c.textContent = 'copiar', 1400); };
      (navigator.clipboard ? navigator.clipboard.writeText(txt) : Promise.reject()).then(done).catch(() => { const ta = document.createElement('textarea'); ta.value = txt; document.body.append(ta); ta.select(); try { document.execCommand('copy'); } catch(x){} ta.remove(); done(); });
    }
  });
  ritFilter();
  /* índice lateral */
  const g = document.createElement('div'); g.className = 'ix-g'; g.dataset.tab = 'regimento';
  g.innerHTML = `<button>Regimento</button><ul>${[['rit-mapa','Mapa do Regimento'],['rit-gab','No dia a dia do gabinete'],['rit-texto','Texto integral'],['rit-assentos','Assentos regimentais']].map(([id, t]) => `<li><a href="#" data-target="${id}"><i></i>${t}</a></li>`).join('')}
    ${RIT_TREE.kids.map(p => `<li><a href="#" data-rith="${p.id}" style="--fc:var(--m-rit)"><i></i>${p.k}</a></li>${p.kids.map(t => `<li class="ixs"><a href="#" data-rith="${t.id}" style="--fc:var(--m-rit)"><i></i>${t.k.replace('Título ', 'T. ')} · ${escH(t.t.length > 34 ? t.t.slice(0, 33) + '…' : t.t)}</a></li>`).join('')}`).join('')}</ul>`;
  $('#index').append(g);
  g.querySelector(':scope > button').onclick = () => scrollTo({ top:0, behavior:'smooth' });
  g.querySelectorAll('a[data-target]').forEach(a => a.onclick = e => { e.preventDefault(); goTo('regimento', a.dataset.target); });
  g.querySelectorAll('a[data-rith]').forEach(a => a.onclick = e => { e.preventDefault(); ritGoHead(a.dataset.rith); });
  /* busca global */
  IDX.push(...Object.values(RITA).map(a => ({ k:'RITRF3', t:'Art. ' + ritLabel(a.n), s:ritStrip(a.b[0][1]).slice(0, 140), txt:RITTXT[a.n], go:() => ritGo(a.n) }))
    .map(i => ({ ...i, low:i.txt.toLowerCase() })));
}
