function refreshPainel2(){
  if (!document.getElementById('p2-tar')) return;
  /* Tarefas PJe */
  const T = tkTot();
  $('#p2-tar').innerHTML = !tkLoaded()
    ? `<p class="p-empty">Sem contagem do acervo. Importe o relatório do PJe para ver as caixas mais cheias e o peso de cada estação.</p>
       <div class="p2-act"><label class="chipbtn pri" for="tkfile">Importar relatório…</label><a href="#" class="lnk" data-p2go="tarefas:tk-mapa">abrir o fluxograma →</a></div>`
    : `<div class="p2-stack">${STN.map(s => `<i style="--fc:var(${s.c});width:${T ? 100 * stTot(s.id) / T : 0}%" title="${s.t}: ${fmtN(stTot(s.id))}"></i>`).join('')}</div>
       <div class="p2-kpis"><div><span>Nas caixas</span><b>${fmtN(T)}</b></div>${STN.slice(0, 5).map(s => `<div style="--fc:var(${s.c})"><span>${s.t}</span><b>${fmtN(stTot(s.id))}</b></div>`).join('')}</div>
       <div class="vias">${[...TK].sort((a, b) => tkN(b) - tkN(a)).slice(0, 4).map(t => `<div class="via" style="--fc:var(${stById[t.st].c})"><div class="via-m"><button class="via-n" data-tk="${t.id}">${t.nome}</button><span class="via-p">${fmtN(tkN(t))}</span><small>${stripH(t.serve).slice(0, 96)}…</small></div></div>`).join('')}</div>
       <div class="p2-act"><a href="#" class="lnk" data-p2go="tarefas:tk-mapa">fluxograma interativo →</a><a href="#" class="lnk" data-p2go="tarefas:tk-caixas">todas as caixas →</a></div>`;
  /* Competência */
  const cv = [...(pref.conv || [])].sort((a, b) => a.d.localeCompare(b.d)).filter(c => impDias(c.d) >= 0);
  const nx = cv[0];
  $('#p2-comp').innerHTML = `
    ${nx ? `<div class="p2-conv"><div class="cv-d"><b>${nx.d.slice(8, 10)}</b><span>${new Date(nx.d + 'T12:00:00').toLocaleDateString('pt-BR', { month:'short' }).replace('.', '')}</span></div>
      <div><span class="p2-k">Próxima convocação · impedimento e suspeição</span><b>${escH(convSecLabel(nx.s))}</b><small>${impFmtD(nx.d)} · ${impDias(nx.d) === 0 ? 'hoje' : 'em ' + impDias(nx.d) + ' dias'}${cv[1] ? ` · depois: ${escH(convSecLabel(cv[1].s))}, ${impFmtD(cv[1].d)}` : ''}</small></div></div>` : '<p class="p-empty">Nenhuma convocação futura cadastrada.</p>'}
    <span class="p2-k">Verificar impedimento ou suspeição</span>
    <input id="p2imq" class="p2-in" type="search" placeholder="Número do processo, advogado ou OAB…" aria-label="Verificar impedimento">
    <div id="p2imr" class="p2-res"></div>
    <div class="p2-secs">${SEC.map(s => `<button data-p2go="competencia:sec-secoes" title="${s.t}"><b>${s.n}</b><small>${s.m.slice(0, 3).map(m => m.replace(/^Direito Privado: /, '').replace(/,? ?—.*$/, '').replace(/ ressalvad.*$/, '')).join(' · ')}…</small></button>`).join('')}</div>
    <div class="p2-act"><a href="#" class="lnk" data-p2go="competencia:sec-imped">impedimentos e suspeições →</a><a href="#" class="lnk" data-p2go="competencia:sec-assuntos">assuntos recorrentes →</a></div>`;
  $('#p2imq').oninput = () => { const v = $('#p2imq').value; $('#p2imr').innerHTML = v.trim() ? impCheckHTML(v) : ''; };
}
function buildPainel2(){
  /* Léxico */
  const lexRender = () => {
    const q = $('#p2lq').value.trim().toLowerCase();
    const L = (q ? LEX.filter(x => (x.t + ' ' + x.lat + ' ' + x.d).toLowerCase().includes(q)) : LEX.filter((_, i) => i % 3 === 0)).slice(0, 6);
    $('#p2lr').innerHTML = L.length ? L.map(x => { const g = LEXG.find(y => y.id === x.g);
      return `<button class="p2-term" data-term="${escH(x.t)}" style="--fc:var(${g.c})"><b>${x.t}</b><span>${x.d}</span></button>`; }).join('') : '<p class="p-empty">Nenhum verbete com esse termo.</p>';
  };
  $('#p2-lex').innerHTML = `<input id="p2lq" class="p2-in" type="search" placeholder="Buscar verbete: preparo, devolutivo, prequestionamento…" aria-label="Buscar no léxico"><div id="p2lr" class="p2-terms"></div>
    <div class="p2-act"><a href="#" class="lnk" data-p2go="lexico:lex">todo o léxico →</a></div>`;
  $('#p2lq').oninput = lexRender; lexRender();
  /* Regimento */
  const ritRender = () => {
    const q = $('#p2rq').value.trim().toLowerCase();
    let ks;
    if (!q) ks = RIT_KEY_ARTS.slice(0, 6).map(a => a[0]);
    else { const num = q.replace(/^art(igo)?s?\.?\s*/, '').replace(/[º°\s]/g, '');
      ks = /^\d+[a-z]?$/i.test(num) ? [ritKey(num)].filter(k => RITA[k]) : Object.keys(RITA).filter(k => RITTXT[k].toLowerCase().includes(q)).slice(0, 6); }
    $('#p2rr').innerHTML = ks.length ? ks.map(k => { const lab = (RIT_KEY_ARTS.find(a => a[0] === k) || [])[1];
      return `<button class="p2-art" data-ritgo="${k}"><b>Art. ${ritLabel(k)}${lab ? ` · ${lab}` : ''}</b><span>${escH(ritStrip(RITA[k].b[0][1]).slice(0, 150))}${RITA[k].b[0][1].length > 150 ? '…' : ''}</span></button>`; }).join('') : '<p class="p-empty">Nenhum artigo encontrado.</p>';
  };
  $('#p2-rit').innerHTML = `<input id="p2rq" class="p2-in" type="search" placeholder="Artigo ou termo: 33, sustentação oral, embargos…" aria-label="Buscar no Regimento"><div id="p2rr" class="p2-arts"></div>
    <div class="p2-act"><a href="#" class="lnk" data-p2go="regimento:rit-texto">texto integral →</a><a href="#" class="lnk" data-p2go="regimento:rit-mapa">mapa do Regimento →</a></div>`;
  $('#p2rq').oninput = ritRender; ritRender();
  /* Recursos: prazos rápidos */
  $('#p2-rec').innerHTML = `<div class="p2-prz">${R.map(r => `<button data-ficha="${r.id}" style="--fc:var(--rc-${r.id})"><b>${r.nome}</b><span>${shortPrazo(r.prazo)}</span></button>`).join('')}</div>
    <p class="p-note">Dias úteis (CPC, art. 219); em dobro para Fazenda, MP e Defensoria. <a href="#" class="lnk" data-p2go="recursos:sec-agravo">qual agravo? →</a></p>`;
  refreshPainel2();
  document.addEventListener('click', e => { const a = e.target.closest && e.target.closest('[data-p2go]'); if (!a) return; e.preventDefault(); const [tab, id] = a.dataset.p2go.split(':'); goTo(tab, id); });
  document.addEventListener('click', e => { const a = e.target.closest && e.target.closest('#painel [data-term]'); if (!a) return; e.preventDefault(); gotoTerm(a.dataset.term); });
}
buildPainel2();


