  const tsb = add('p-ass', p3Section('p-tes', '--m-lex', 'Teses vinculantes à mão', ''));
  tsb.innerHTML = `<p class="p-note" style="margin-top:0">Passe o cursor sobre cada uma para ler a tese.</p>${P3_TESES.map(g => `<span class="p2-k" style="color:var(${g.c})">${g.t}</span><div class="p3-tes">${g.l.map(t => `<span>${t}</span>`).join('')}</div>`).join('')}`;
  /* Verbete do dia, entre Léxico e Regimento */
  const day = Math.floor(Date.now() / 864e5), vx = LEX[day % LEX.length], vg = LEXG.find(g => g.id === vx.g);
  const vb = add('p-lex', p3Section('p-verb', '--m-lex', 'Verbete do dia', 'lexico:lex'));
  vb.innerHTML = `<div class="p3-verb" style="--fc:var(${vg.c})"><span class="p2-k" style="color:var(${vg.c})">${vg.t} · ${vx.lat}</span><h4>${vx.t}</h4><p>${vx.d}</p>
      <ul class="bul">${vx.det.slice(0, 3).map(d => `<li>${d}</li>`).join('')}</ul><div class="gab"><b>No gabinete ·</b> ${vx.gab}</div>
      <div class="p2-act"><a href="#" class="lnk" data-term="${escH(vx.t)}">abrir o verbete →</a></div></div>
    <span class="p2-k">Os verbos do dispositivo</span>
    <div class="p3-verbs"><span style="--fc:var(--muted)"><b>Não conheço</b>barrado na admissibilidade</span><span style="--fc:var(--navy)"><b>Conheço</b>passa ao mérito</span><span style="--fc:var(--green)"><b>Dou provimento</b>reforma ou anula</span><span style="--fc:var(--wine)"><b>Nego provimento</b>mantém a decisão</span></div>`;
  /* Regimento: artigos-chave e artigo do dia */
  const rb = document.querySelector('#p2-rit');
