/* =================== V18 · ALVENARIA NA ABA ESCUDO =================== */
(() => {
  const grid = document.querySelector('#painel .pgrid'); if (!grid) return;
  const panels = [...grid.querySelectorAll(':scope > .pc')];
  const mas = document.createElement('div'); mas.className = 'p3-mas'; mas.id = 'p3-mas';
  grid.append(mas);
  let last = '';
  const ncols = w => w >= 1460 ? 4 : w >= 1060 ? 3 : w >= 700 ? 2 : 1;
  function layout(){
    if ($('#painel').hidden) return;
    const w = mas.clientWidth || grid.clientWidth; if (!w) return;
    const n = ncols(w);
    let cols = [...mas.children];
    if (cols.length !== n){
      mas.innerHTML = ''; cols = [];
      for (let i = 0; i < n; i++){ const c = document.createElement('div'); c.className = 'p3-col'; mas.append(c); cols.push(c); }
      panels.forEach(p => cols[0].append(p));
    }
    /* mede cada painel na largura da coluna e distribui, em ordem, pela coluna mais curta */
    const gap = 14, hs = panels.map(p => p.offsetHeight), tot = new Array(n).fill(0), pick = [];
    panels.forEach((p, i) => { let k = 0; for (let j = 1; j < n; j++) if (tot[j] < tot[k] - 1) k = j; pick.push(k); tot[k] += hs[i] + gap; });
    const sig = n + ':' + pick.join('');
    if (sig === last && panels.every((p, i) => p.parentElement === cols[pick[i]])) return;
    last = sig;
    panels.forEach((p, i) => cols[pick[i]].append(p));
  }
  let raf = 0; const queue = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(layout); };
  const ro = new ResizeObserver(queue);
  ro.observe(mas); panels.forEach(p => ro.observe(p));
  addEventListener('resize', queue);
  window.p3Layout = queue;
  window.p3Add = (el, afterId) => {
    const i = panels.findIndex(p => p.id === afterId); panels.splice(i < 0 ? panels.length : i + 1, 0, el);
    (mas.firstElementChild || mas).append(el); ro.observe(el); last = '';
    panels.forEach((p, k) => { const r = p.querySelector('.pc-h .rn'); if (r) r.textContent = (typeof P3_ROMAN !== 'undefined' && P3_ROMAN[k]) || k + 1; });
    const ix = document.querySelector('#index .ix-g[data-tab="painel"] ul'), prev = ix && ix.querySelector(`a[data-target="${afterId}"]`);
    if (prev){ const h = el.querySelector('.pc-h').cloneNode(true); h.querySelectorAll('.rn,.pc-go').forEach(x => x.remove());
      const li = document.createElement('li'); li.innerHTML = `<a href="#" data-target="${el.id}" style="--fc:${el.style.getPropertyValue('--mod')}"><i></i>${h.textContent.trim()}</a>`;
      prev.parentElement.after(li); li.querySelector('a').onclick = e => { e.preventDefault(); goTo('painel', el.id); }; }
    queue();
  };
  queue();
})();


/* =================== V19 · FLUXOS E ROTINA (Rotina unificada às Tarefas do PJe) =================== */
const PH_TK = {
  chegada:['rec_unid','triagem','analisar'], urgencia:['minutar','s_interc','sob_min'], minuta:['analisar','minutar','revisar','revisar_div','assinar','s_prep'],
  dispositivo:['minutar','s_prep','s_inteiro'], sessao:['s_aptos','s_aguard','s_ret','s_interc'], pos:['s_inteiro','rec_ed','ed_min','agint_min','sed_prep','sed_aguard'],
  vice:['sob_ts','su_ts','su_irdr','sob_pet','su_pet','sob_min'], regim:['s_interc'], baixa:[]
};
(() => {
  const rot = $('#rotina'), tar = $('#tarefas'); if (!rot || !tar) return;
  /* 1. leva as etapas da Rotina para dentro do módulo, entre o fluxograma e as caixas */
  const sec = document.createElement('section'); sec.className = 'blk'; sec.id = 'tk-rotina';
  sec.innerHTML = '<h2>Rotina do gabinete <small class="h2s">da chegada à baixa, etapa por etapa · os checklists podem ser marcados enquanto se trabalha</small></h2>';
  sec.append($('#rotidx'), $('#rotbody'));
  $('#tk-caixas').before(sec);
  rot.remove();
  /* 2. cada etapa mostra as caixas do PJe em que acontece */
  PHASES.forEach(p => {
    const ids = PH_TK[p.id] || [], head = document.querySelector(`#ph-${p.id} .ph-head > div`);
    if (!head || !ids.length) return;
    head.insertAdjacentHTML('beforeend', `<div class="ph-tk"><span>Caixas do PJe</span>${ids.map(id => `<button data-tk="${id}" style="--fc:var(${stById[tkById[id].st].c})">${tkById[id].nome}</button>`).join('')}</div>`);
  });
  if (PH_TK.baixa){ const h = document.querySelector('#ph-baixa .ph-head > div'); if (h) h.insertAdjacentHTML('beforeend', '<div class="ph-tk"><span>Caixas do PJe</span><button data-p2go="tarefas:tk-fluxos" style="--fc:var(--wine)">Certificar trânsito · Remessa para 1º grau · Arquivamento</button></div>'); }
  /* 3. cabeçalho, aba e endereço */
  const h = tar.querySelector(':scope > .pane-head');
  h.querySelector('h1').textContent = 'Fluxos e Rotina';
  h.querySelector('p').textContent = 'O acervo, o fluxograma, a rotina da chegada à baixa e, em cada caixa do PJe, o que ela guarda e o que se faz nela.';
  h.dataset.eb = 'Painel do PJe · rotina do gabinete';
  document.querySelector('.mods .mod[data-tab="rotina"]')?.remove();
  const mb = document.querySelector('.mods .mod[data-tab="tarefas"]'); if (mb) mb.textContent = 'Fluxos e Rotina';
  const TAB_ALIAS = { rotina:'tarefas' };
  const _show = showTab;
  showTab = function(t){ return _show(TAB_ALIAS[t] || t); };
  const _go = goTo;
  goTo = function(tab, id){ return _go(TAB_ALIAS[tab] || tab, id); };
  goRot = function(id){ goTo('tarefas', 'ph-' + id); };
  /* 4. índice lateral: um só grupo, com a rotina no meio */
  const gr = document.querySelector('#index .ix-g[data-tab="rotina"]'), gt = document.querySelector('#index .ix-g[data-tab="tarefas"]');
  if (gt){
    gt.querySelector(':scope > button').textContent = 'Fluxos e Rotina';
    const ul = gt.querySelector('ul');
    const order = [['tk-panorama','Panorama do acervo'],['tk-leitura','Leitura do acervo'],['tk-mapa','Fluxograma interativo'],['tk-rotina','Rotina do gabinete']];
    const top = order.map(([id, t]) => `<li><a href="#" data-target="${id}"><i></i>${t}</a></li>`).join('')
      + PHASES.map(p => `<li class="ixs"><a href="#" data-target="ph-${p.id}" style="--fc:var(--m-rot)"><i></i>${p.n}. ${p.t}</a></li>`).join('');
    [...ul.querySelectorAll('a[data-target="tk-panorama"],a[data-target="tk-mapa"],a[data-target="tk-leitura"]')].forEach(a => a.parentElement.remove());
    ul.insertAdjacentHTML('afterbegin', top);
    ul.querySelectorAll('a[data-target]').forEach(a => a.onclick = e => { e.preventDefault(); goTo('tarefas', a.dataset.target); });
  }
  gr && gr.remove();
  /* 5. busca global e atalhos que apontavam para a Rotina */
  IDX.forEach(x => { if (x.k === 'Rotina') x.k = 'Fluxos e Rotina'; });
  if (/^#rotina/.test(location.hash)) showTab('tarefas');
  if (typeof refreshPainel2 === 'function') refreshPainel2();
})();


