  'Assinatura da peça':{ b:'CPC, arts. 76 e 932, p. ú.', tk:['minutar'], ph:'chegada' },
  'Intempestividade':{ b:'CPC, arts. 1.003, §5º, e 932, III', tk:['minutar'], ph:'chegada', v:'Tempestividade' },
  'Deserção':{ b:'CPC, arts. 1.007, §4º, e 932, III', tk:['minutar'], ph:'chegada', v:'Deserção' },
