    b.innerHTML = `<div class="tbl acv-tw"><table class="acv-t"><thead><tr><th>Processo</th><th>Classe · assunto</th><th>Partes</th><th>Na caixa</th><th>Etiquetas</th></tr></thead><tbody>${L.slice(0, 400).map(o => acvRow(o, nm(o))).join('')}</tbody></table></div>${L.length > 400 ? `<p class="p-note">Mostrando os 400 mais antigos de ${L.length}.</p>` : ''}`;
