  const csv = '﻿' + [cols.map(c => q(c.t)).join(';'), ...L.map(o => cols.map(c => { const v = c.v(o); return q(c.date ? acvDate(v) : c.money && v != null ? Number(v).toFixed(2).replace('.', ',') : v); }).join(';'))].join('\r\n');
