  if (c.column === '__busca__'){ const hay = acsCanon(Object.keys(ACS_COLS).map(k => acsVals(o, k).join(' ')).join(' ')); const t = n => hay.includes(acsCanon(n)); return c.combine === 'all' ? c.values.every(t) : c.values.some(t); }
