  if (!adv.length && !orig.length){ el.innerHTML = '<p class="im-ok">✓ Nenhum processo do filtro atual tem advogado das listas ou origem que peça conferência.</p>'; return; }
  const bySec = {}; adv.forEach(o => (bySec[o.secao] = bySec[o.secao] || []).push(o));
