  Object.values(ACV.comp).forEach(src => Object.entries(src.map).forEach(([key, d]) => { if (idx.has(key)) return;
    const o = M.get(key) || { p:d.p, src:[] }; if (!o.src.includes(src.kind)) o.src.push(src.kind);
    Object.entries(d).forEach(([k, v]) => { if (k !== 'p' && k !== 'x' && (o[k] == null || o[k] === '')) o[k] = v; }); M.set(key, o); }));
