pref.impAdvJ = pref.impAdvJ && typeof pref.impAdvJ === 'object' ? pref.impAdvJ : {};
const alJName = k => k === '*' ? 'qualquer alerta' : k === '?' ? 'julgador a confirmar' : ((IMP_JUIZ.find(j => j.id === k) || {}).n || k);
const alJOf = x => x.k === 'orig' ? x.j.id : (x.a.j || pref.impAdvJ[x.a.o] || '?');
function alJMatch(o, k){ const a = acvAl(o); if (!a.length) return false; return k === '*' || a.some(x => alJOf(x) === k); }
const _acsCM = acsCritMatch;
acsCritMatch = function(o, c){ return c.alj ? alJMatch(o, c.alj) : _acsCM(o, c); };
function alFilterRow(){
  const saved = ACS.crit; ACS.crit = saved.filter(c => !c.alj); const F = acvFiltered(); ACS.crit = saved;
  const act = new Set(saved.filter(c => c.alj).map(c => c.alj));
  const cnt = k => F.filter(o => alJMatch(o, k)).length;
  const det = k => { const L = F.filter(o => alJMatch(o, k)), t = { imp:0, susp:0, orig:0 };
    L.forEach(o => new Set(acvAl(o).filter(x => k === '*' || alJOf(x) === k).map(x => x.k)).forEach(z => t[z]++));
    return [t.imp && `${t.imp} imp.`, t.susp && `${t.susp} susp.`, t.orig && `${t.orig} origem`].filter(Boolean).join(' · ') || 'nenhum'; };
  const keys = ['*', ...IMP_JUIZ.map(j => j.id), ...(IMP_ADV.some(a => !(a.j || pref.impAdvJ[a.o])) ? ['?'] : [])];
  return `<div class="acs-grp acs-al"><span>VERIFICAR IMPEDIMENTO / SUSPEIÇÃO</span>${keys.map(k => `<button class="${act.has(k) ? 'on' : ''}" data-alj="${k}" title="${escH(k === '?' ? 'Advogados das listas ainda sem julgador definido (aba Competência)' : det(k))}">${k === '*' ? 'Qualquer alerta' : alJName(k)}<b>${cnt(k).toLocaleString('pt-BR')}</b><em>${det(k)}</em></button>`).join('')}<a href="#" class="lnk" data-p2go="competencia:sec-imped" title="Definir o julgador de cada advogado na tabela da Competência">definir julgadores →</a></div>`;
}
const _acsPanel = acsPanel;
