/* ---- V30 · "Onde está o processo": estações do fluxo no lugar dos agrupadores ---- */
const EST_OUT = [
  { id:'x-dist', t:'Distribuição e prevenção', c:'--azul', re:/analise da distribuicao|retificar autuacao|processos ja analisados|cancelamento da distribuicao|cumprir determinacoes do magistrado|recebido pelo distribuidor|recebidos do juizo de origem/ },
  { id:'x-dilig', t:'Diligências, MPF e cumprimento', c:'--rc-rn', re:/diligencia|mpf|contadoria|calculo|cumprir|conciliacao|\[inss\]|comunicacao ao juizo|determinacoes/ },
  { id:'x-prazo', t:'Prazos, intimações e acórdão', c:'--gold', re:/prazo em curso|intimac|djen|nao intimados|preparar comunicacao|preparar expediente|aguardando expedicao|analisar manifestacao|decurso|certidao/ },
  { id:'x-saida', t:'Baixa, trânsito e arquivo', c:'--wine', re:/baixados|arquivo|transito|remessa|remeter|pendencias anteriores|remetidos/ },
  { id:'x-out', t:'Outras caixas', c:'--muted', re:/./ }
];
const EST_IN = STN.flatMap(x => x.id === 'sessao' ? [{ id:'sessao', t:'Sessão · aguardando inclusão em pauta', c:x.c }, { id:'sessao-p', t:'Sessão · pautados (aguardando a sessão)', c:'--rc-resp' }]
  : x.id === 'sed' ? [{ id:'sed', t:'ED · aguardando inclusão em pauta', c:x.c }, { id:'sed-p', t:'ED · pautados (aguardando a sessão)', c:'--rc-aresp' }] : [x]);
const estName = id => (EST_IN.find(x => x.id === id) || EST_OUT.find(x => x.id === id) || {}).t || id;
function estOfTask(t){ const c0 = acsCanon(t); if (/^\[sessao\] aguardando (a sessao|julgamento colegiado)/.test(c0)) return 'sessao-p'; if (/^\[sessao - ed\] aguardando (a sessao|julgamento colegiado)/.test(c0)) return 'sed-p';
  const g = PJEF_TK[pjeNorm(t)]; if (g) return tkById[g].st; const c = c0;
  if (/^\[sessao - ed\] aguardando/.test(c)) return 'sed'; if (/^\[sessao\] (aguardando|assinar|revisar|minutar|confirmar|lancar)/.test(c)) return 'sessao';
  if (/^minutar acordao|^minutar ato ordinatorio|^avaliar tipo de recurso/.test(c)) return 'mono'; return (EST_OUT.find(x => x.re.test(c)) || {}).id; }
const estOf = o => [...new Set(o.tks.map(x => estOfTask(x.t)).filter(Boolean))];
const _acsCM2 = acsCritMatch;
acsCritMatch = function(o, c){ if (c.est) return estOf(o).includes(c.est); if (c.tkn) return o.tks.some(x => x.t === c.tkn); return _acsCM2(o, c); };
function estRow(){
  const saved = ACS.crit; ACS.crit = saved.filter(c => !c.est && !c.tkn && !c.grupo); const F = acvFiltered(); ACS.crit = saved;
  const act = new Set(saved.filter(c => c.est).map(c => c.est)), actT = new Set(saved.filter(c => c.tkn).map(c => c.tkn));
  const cnt = {}, tks = {}; F.forEach(o => { estOf(o).forEach(e => cnt[e] = (cnt[e] || 0) + 1); o.tks.forEach(x => { const e = estOfTask(x.t); if (!e) return; (tks[e] = tks[e] || new Map()).set(x.t, ((tks[e] || new Map()).get(x.t) || 0) + 1); }); });
  const chip = x => `<button class="est-c${act.has(x.id) ? ' on' : ''}${cnt[x.id] ? '' : ' z'}" data-est="${x.id}" style="--fc:var(${x.c})" title="${escH([...(tks[x.id] || new Map()).keys()].join(' · ') || 'nenhum processo no filtro atual')}"><i></i><span>${x.t}</span><b>${(cnt[x.id] || 0).toLocaleString('pt-BR')}</b></button>`;
  const open = [...act].filter(e => tks[e]);
  return `<div class="acs-est"><div class="est-h"><span>ONDE ESTÁ O PROCESSO</span><em>estações do fluxo · clique para filtrar, várias somam (OU) · ao escolher uma, aparecem as caixas dela</em></div>
    <div class="est-g"><small>No gabinete</small>${EST_IN.map(chip).join('')}</div>
    <div class="est-g"><small>Fora do gabinete</small>${EST_OUT.filter(x => x.id !== 'x-out' || cnt[x.id]).map(chip).join('')}</div>
    ${open.map(e => `<div class="est-t" style="--fc:var(${(EST_IN.find(x => x.id === e) || EST_OUT.find(x => x.id === e)).c})"><small>${estName(e)} · caixas</small>${[...tks[e].entries()].sort((a, b) => b[1] - a[1]).map(([t, n]) => `<button class="${actT.has(t) ? 'on' : ''}" data-tkn="${escH(t)}">${escH(t)}<b>${n.toLocaleString('pt-BR')}</b></button>`).join('')}</div>`).join('')}</div>`;
}
const _acsPanel2 = acsPanel;
