  const _p = acsPanel; acsPanel = function(){ _p(); document.querySelector('#acspanel .acs-al')?.remove(); };
  const _r = acvRender; acvRender = function(){ _r(); document.querySelectorAll('#acvkpi .al-k').forEach(x => x.remove()); impAcvRender(); };
  /* o ⚠ nas tabelas do acervo continua, e leva à Competência */
  document.addEventListener('click', e => { const b = e.target.closest && e.target.closest('.al-badge'); if (!b) return; e.preventDefault(); e.stopPropagation(); goTo('competencia', 'sec-impacv'); }, true);
  /* avisos do Escudo levam à Competência */
  document.addEventListener('click', e => { const b = e.target.closest && e.target.closest('[data-algo]'); if (!b) return; e.preventDefault(); e.stopImmediatePropagation(); goTo('competencia', 'sec-impacv'); }, true);
  /* julgador ou convocação alterados: atualiza */
