  if (ul){ const li = document.createElement('li'); li.innerHTML = '<a href="#" data-target="sec-impacv"><i></i>Processos a verificar</a>'; const ref = ul.querySelector('a[data-target="sec-secoes"]'); ref ? ref.parentElement.before(li) : ul.append(li);
    li.querySelector('a').onclick = e => { e.preventDefault(); goTo('competencia', 'sec-impacv'); }; }
  IDX.forEach(x => { if (x.t === 'Alertas de impedimento e suspeição'){ x.k = 'Competência'; x.s = 'Processos do acervo a verificar: por advogado/parte e por origem/data'; x.go = () => goTo('competencia', 'sec-impacv'); } });
  if (ACV.recs) acvRender(); else impAcvRender();
