/* ---- V36 · situações processuais dentro dos cartões de indicadores ---- */
const KC_SUB = {
  'processos':{ f:() => true }, 'no gabinete':{ f:o => o.gab }, 'fora do gabinete':{ f:o => !o.gab },
  'em tramitação':{ f:o => o.sit === 'tram', only:['tram'] }, 'julgados':{ f:o => o.sit === 'julg', only:['julg'] }, 'baixados':{ f:o => o.sit === 'baix', only:['baix'] },
  'sobrestados':{ f:o => o.sit === 'sobr' || o.sit === 'susp', only:['sobr', 'susp'] }, 'com prioridade':{ f:o => o.pri },
  'conclusos':{ f:o => o.cx && o.cx.concl === 'Sim' }, 'segredo de justiça':{ f:o => o.cx && o.cx.sig }
};
const SIT_SHORT = { tram:'Tramitação', adiam:'Adiamento', arq:'Arquivado', baix:'Baixado', canc:'Cancelado', crsf:'Com. Fundiária', digit:'Digitalizado', dilig:'Diligência', elim:'Eliminado', sup:'Inst. superior', ip:'Inquérito', julg:'Julgado', fora:'Fora de tramit.', inss:'INSS', stf:'STF', stj:'STJ', ts:'Trib. superiores', sobr:'Sobrestado', plant:'Plantão', susp:'Suspenso', vp:'Vice-Presid.' };
function kcSits(){
  const k = $('#acvkpi'); if (!k || !ACV.recs) return;
  const F = acvFiltered();
  k.querySelectorAll('.p3-k').forEach(card => {
    card.querySelector('.kc-sit')?.remove();
    const lab = acsCanon(card.querySelector('span')?.textContent || '').replace(/^⚠\s*/, ''), def = Object.entries(KC_SUB).find(([n]) => acsCanon(n) === lab);
    if (!def) return;
    const L = F.filter(def[1].f), cnt = {}; L.forEach(o => cnt[o.sit] = (cnt[o.sit] || 0) + 1);
    let rows = Object.entries(cnt).sort((a, b) => b[1] - a[1]);
    const hidden = (def[1].only || []).filter(x => ACS.hide.has(x));
    const chips = rows.slice(0, 5).map(([s, n]) => `<i style="--fc:var(${SIT_BY[s].c})" title="${SIT_BY[s].t}: ${n}"><u></u>${SIT_SHORT[s] || SIT_BY[s].t} <b>${n.toLocaleString('pt-BR')}</b></i>`).join('') + (rows.length > 5 ? `<i class="more" title="${rows.slice(5).map(([s, n]) => SIT_BY[s].t + ': ' + n).join(' · ')}">+${rows.length - 5}</i>` : '');
    const note = hidden.length ? `<em data-acssitc="${hidden[0]}" title="Mostrar esta situação nos resultados">${hidden.map(x => SIT_BY[x].t).join(', ')}: oculta no filtro · mostrar</em>` : '';
    card.insertAdjacentHTML('beforeend', `<div class="kc-sit">${chips || (note ? '' : '<i class="z">nenhum processo</i>')}${note}</div>`);
  });
}
(() => {
  const _r = acvRender; acvRender = function(){ _r(); kcSits(); };
  const _p = acsPanel; acsPanel = function(){ _p(); kcSits(); };
  if (ACV.recs) acvRender();
})();


(() => {
  document.addEventListener('click', e => { const em = e.target.closest && e.target.closest('.kc-sit em[data-acssitc]'); if (!em) return; e.preventDefault(); e.stopPropagation();
    const h = new Set(ACS.hide); h.delete(em.dataset.acssitc); acsSetHide([...h]); }, true);
  const _set = acvSet;
  acvSet = function(k, v){ if (k === 'sit' && ACS.hide.has(v) && ACV.st.f.sit !== v){ ACS.hide.delete(v); pref.ui.acsHide = [...ACS.hide]; persist(); } return _set(k, v); };
})();


/* =================== V37 · ASSUNTOS SEM SEÇÃO VINCULADOS · ASSUNTO → ACERVO =================== */
