const RP_WIN = '€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ';
const rpTx = s => String(s == null ? '' : s).replace(/[→⟶]/g, '->').replace(/[≥]/g, '>=').replace(/[≤]/g, '<=').replace(/[✓✔]/g, 'ok').replace(/ | /g, ' ').replace(/./gu, c => c.charCodeAt(0) < 256 || RP_WIN.includes(c) ? c : '');
/* ---------- gerar o documento ---------- */
function rpDoc(){
  const M = RL.M || (RL.M = rlModel()), R = RP_CAT.find(r => r.id === RP.id);
  if (R.o.includes('obj') && !RP.opt.obj){ const L = R.objs(M); RP.opt.obj = L.length ? L[0][0] : ''; }
  const sub = [R.o.includes('sec') || R.o.includes('secreq') ? (R.o.includes('secreq') && RP.opt.sec === 'Todas' ? '1ª Seção' : rpSecLbl()) : '', R.o.includes('obj') ? RP.opt.obj.replace(' OAB:', ' · OAB') : ''].filter(Boolean).join(' · ');
  const ctx = { v:2, relatorio:R.id, sec:(R.o.includes('sec') || R.o.includes('secreq')) ? (RP.opt.sec === 'Todas' && R.o.includes('secreq') ? '1ª Seção' : RP.opt.sec) : null,
    objeto:R.o.includes('obj') ? RP.opt.obj : null, criterios:R.id === 'filtro' ? { busca:ACS.q || '', regras:ACS.crit || [] } : null,
    somenteAptos:R.o.includes('aptos') ? !!RP.opt.aptos : null, incluirPossivelImpedimento:R.o.includes('imp') ? !!RP.opt.imp : null,
    limite:R.o.includes('lim') ? RP.opt.lim : null, universo:R.id === 'filtro' ? 'filtro-do-acervo' : (R.id === 'fluxo' ? 'extracao-atual-eventos' : 'gabinete-tramitacao-adiados') };
  const fonte = ACV.src || 'Base consolidada do Acervo';
  const src = `${fonte}${ACV.d ? ' · data-base declarada: ' + ACV.d : ' · data-base não informada'}${ACV.at ? ' · importado/atualizado em ' + ACV.at : ''}`;
  const blocks = R.b(M).filter(b => b && !(b.note === ''));
  if (R.id !== 'filtro') blocks.push({ note:`Rastreabilidade: ${M.qualidade.totalUnicos.toLocaleString('pt-BR')} registros únicos no recorte completo; ${M.qualidade.duplicados} duplicidade(s) de CNJ detectada(s) na fonte; ${M.qualidade.semTarefa} processo(s) ativos sem tarefa identificada; ${M.qualidade.semTempoNaTarefa} sem informação de tempo na tarefa. Os indicadores de aptidão, metas, prioridade e incidentes dependem da qualidade dos registros e não substituem a conferência dos autos.` });
  return { title:R.t, sub, src, ctx, uni:ctx.universo === 'gabinete-tramitacao-adiados' ? 'Processos nas caixas de tramitação ou adiados, excluídos sobrestados e baixados (salvo indicação expressa)' : ctx.universo === 'extracao-atual-eventos' ? 'Apenas eventos identificados nos processos presentes na extração atual' : 'Processos do filtro aplicado no Acervo', blocks };
}
