function rpFonte(doc){
  try {
    doc.addFileToVFS('Carlito-Regular.ttf', RP_FONT.r); doc.addFont('Carlito-Regular.ttf', 'Carlito', 'normal');
    doc.addFileToVFS('Carlito-Bold.ttf', RP_FONT.b); doc.addFont('Carlito-Bold.ttf', 'Carlito', 'bold');
    doc.addFileToVFS('Carlito-Italic.ttf', RP_FONT.i); doc.addFont('Carlito-Italic.ttf', 'Carlito', 'italic');
    doc.setFont('Carlito', 'normal'); return 'Carlito';
  } catch (e){ console.warn('[relatórios] fonte Carlito indisponível, usando Helvetica', e); return 'helvetica'; }
}
/* desenha um SVG convertido (caminhos absolutos M/L/C/Z) no retângulo dado; fit: 'none' (estica) | 'slice' (cobre) | 'meet' (cabe) */
function rpSvg(doc, S, x, y, w, h, fit, F, o){
  o = o || {}; const [vx, vy, vw, vh] = S.vb; let sx = w / vw, sy = h / vh, ox = x, oy = y;
  if (fit === 'slice' || fit === 'meet'){ const s = (fit === 'slice' ? Math.max(sx, sy) : Math.min(sx, sy)) * (o.zoom || 1); sx = sy = s; ox = x + (w - vw * s) * (o.ax == null ? .5 : o.ax); oy = y + (h - vh * s) * (o.ay == null ? .5 : o.ay); }
  const X = o.flip ? v => ox + (vx + vw - v) * sx : v => ox + (v - vx) * sx, Y = v => oy + (v - vy) * sy;
  doc.saveGraphicsState(); doc.rect(x, y, w, h, null); doc.clip(); doc.discardPath();
  S.p.forEach(([fill, eo, d, p3]) => {
    const ops = [], re = /([MLCZ])([^MLCZ]*)/g; let m;
    while ((m = re.exec(d))){ const n = m[2].trim() ? m[2].trim().split(/\s+/).map(Number) : [];
      if (m[1] === 'M') ops.push({ op:'m', c:[X(n[0]), Y(n[1])] }); else if (m[1] === 'L') ops.push({ op:'l', c:[X(n[0]), Y(n[1])] });
      else if (m[1] === 'C') ops.push({ op:'c', c:[X(n[0]), Y(n[1]), X(n[2]), Y(n[3]), X(n[4]), Y(n[5])] }); else ops.push({ op:'h', c:[] }); }
    if (p3 != null){ const q = Math.min(1, p3 * (o.opk || 1)); doc.saveGraphicsState(); doc.setGState(new doc.GState({ opacity:q, 'fill-opacity':q })); }
    doc.setFillColor(o.cor || fill); doc.path(ops); if (eo) doc.fillEvenOdd(); else doc.fill();
    if (p3 != null) doc.restoreGraphicsState();
  });
  (S.t || []).forEach(t => { const pt = t.s * sy / 0.3528; doc.setFont(F, 'normal'); doc.setFontSize(pt); doc.setTextColor(t.f);
    const tw = doc.getTextWidth(t.t), alvo = t.w * sx; doc.text(t.t, X(t.x), Y(t.y), { charSpace:t.t.length > 1 ? (alvo - tw) / (t.t.length - 1) : 0 }); });
  doc.restoreGraphicsState();
}
/* texto em trechos (negrito/regular, tamanhos e cores diferentes na mesma linha), quebrado na largura dada */
function rpRuns(doc, F, runs, maxW){
  const ws = []; runs.forEach(r => String(r.t == null ? '' : r.t).split(/(\s+)/).forEach(t => { if (t !== '') ws.push(Object.assign({}, r, { t:/^\s+$/.test(t) ? ' ' : t })); }));
  const largura = w => { doc.setFont(F, w.st || 'normal'); doc.setFontSize(w.sz); return doc.getTextWidth(w.t); };
  const lines = []; let cur = [], cw = 0;
  const fecha = () => { while (cur.length && cur[cur.length - 1].t === ' '){ cw -= cur.pop().ww; } if (cur.length) lines.push({ ws:cur, w:cw, sz:Math.max(...cur.map(w => w.sz)) }); cur = []; cw = 0; };
  ws.forEach(w => { w.ww = largura(w); if (w.t === ' '){ if (cur.length){ cur.push(w); cw += w.ww; } return; } if (cw + w.ww > maxW && cur.length) fecha(); cur.push(w); cw += w.ww; });
  fecha(); return lines;
}
function rpDrawRuns(doc, F, lines, x, y, align, lh){
  lines.forEach(l => { let xx = align === 'right' ? x - l.w : x; l.ws.forEach(w => { doc.setFont(F, w.st || 'normal'); doc.setFontSize(w.sz); doc.setTextColor(...(w.c || RP_COR.ink)); doc.text(w.t, xx, y); xx += w.ww; }); y += lh || l.sz * 0.3528 * 1.18; });
  return y;
}
/* termo em negrito + complemento regular, como nos títulos do manual ("Antiguidade e metas", "Por matéria") */
function rpTermo(t){
  const w = String(t || '').trim().split(/\s+/).filter(Boolean); if (!w.length) return ['', '', false];
  if (w.length > 1 && /^(por|de|do|da|dos|das|em|no|na|para|sobre)$/i.test(w[0])) return [w[0] + ' ', w.slice(1).join(' '), true];
  return [w[0], w.length > 1 ? ' ' + w.slice(1).join(' ') : '', false];
}
