    linhas.forEach(t => { const L = rpRuns(doc, F, [{ t:rpTx(t), sz:8.6, c:C.ink1 }], cw - 9), h = L.length * 4.1 + 4.6; ensure(h + 2); doc.setFillColor(...PL.t); doc.rect(mx, y - 1, cw, h, 'F'); doc.setFillColor(...PL.o); doc.rect(mx, y - 1, .9, h, 'F'); rpDrawRuns(doc, F, L, mx + 4.5, y + 3.3, 'left', 4.1); y += h + 2.5; });
