/* gerador de PDF: jsPDF + AutoTable carregados na primeira vez que um relatório é pedido */
let JSPDF_P = null;
function carregarJsPDF(cb){
  const ok = () => window.jspdf && window.jspdf.jsPDF && window.jspdf.jsPDF.API && window.jspdf.jsPDF.API.autoTable;
  if (ok()){ cb(); return; }
  toast('Carregando o gerador de PDF…');
  const add = src => new Promise((res, rej) => { const el = document.createElement('script'); el.src = src; el.async = true; el.onload = res; el.onerror = () => rej(new Error('falha ao carregar ' + src)); document.head.appendChild(el); });
  JSPDF_P = JSPDF_P || add('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js')
    .then(() => add('https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js'));
  JSPDF_P.then(() => { if (ok()) cb(); else throw new Error('jsPDF sem AutoTable'); })
    .catch(e => { JSPDF_P = null; console.error('[CMT] PDF', e); toast('Não foi possível carregar o gerador de PDF. Verifique a internet e tente de novo.'); });
}
